"use strict";
// Vertalingen van het meldformulier. Nederlands staat in melden.html zelf en
// wordt daaruit opgebouwd; deze tabel bevat de dertien overige talen.
window.VVE_MELDEN_I18N = {
"en":{"anonWarnBack": "Go back, I will enter my tag number", "anonWarnBody": "Without a tag number the board has nothing to act on: no warning, no penalty, no enquiry into a particular apartment. We also cannot ask you anything or let you know what happened. The signal is recorded, but usually nothing changes.", "anonWarnPrivacy": "Your tag number is stored encrypted separately and is never shown to other residents. Only authorised board members can link it to an apartment through the records.", "anonWarnProceed": "Continue anonymously anyway", "anonWarnTitle": "An anonymous report is barely a report", "anonymous": "I do not have a tag number and only want to submit an anonymous signal.", "anonymousHelp": "Without a recognised tag number, we treat the report only as an anonymous signal. A signal alone is not grounds for a warning or penalty.", "attachmentHelp": "Up to 3 files: JPG, PNG or PDF, maximum 2 MB per file. Check file names and contents for unnecessary personal information.", "attachments": "Add evidence (optional)", "captcha": "Complete the security check before sending.", "captchaBlocked": "The security check could not load. Disable any ad blocker or privacy extension for this page, or try a different browser. You can also report by email.", "captchaError": "The security check expired or failed. Please complete it again.", "category": "Type of report", "choose": "Select an option", "close": "Close", "contact": "The board may contact me using the existing VvE records.", "contactHelp": "Only if the tag can be linked to an apartment. The board will contact you using the details registered for your apartment. Under article 20 of the division regulations, owners are required to register their tenants and occupants with the VvE.", "damage": "Damage", "date": "Date of the incident", "description": "Description of the incident", "descriptionHelp": "Describe what you personally saw, heard or smelled. At least 20 characters. Avoid unnecessary names or other personal details. You may write in your own language.", "dirt": "Litter / dirt", "dur1": "Less than 15 minutes", "dur2": "15 minutes to 1 hour", "dur3": "1 to 3 hours", "dur4": "3 to 6 hours", "dur5": "6 to 12 hours", "dur6": "More than 12 hours", "dur7": "Continuous, almost constant", "dur8": "Still going on right now", "duration": "How long did it last?", "durationHelp": "An estimate is enough. Choose \"continuous\" if it is not a single incident.", "emergency": "This form is not for emergencies. Call 112 if there is immediate danger.", "event": "2. What happened?", "fileError": "Use at most 3 JPG, PNG or PDF files, each no larger than 2 MB.", "followup": "3. Follow-up", "futureError": "The incident date cannot be in the future.", "identity": "1. Your access tag", "intro": "You do not need to enter your name or address. Use the number of an access tag issued to your apartment. Only authorised board members and the VvE manager may use the existing tag records to link it to an apartment. Your identity will not be disclosed to other residents without necessity.", "invalid": "Please check the required fields.", "location": "Location or apartment involved", "locationHelp": "Where did it happen? Do not enter your own address as contact information here if you want to remain anonymous.", "navReport": "Report an issue", "navRules": "Building rules", "navUpdates": "Owner updates", "newReport": "Submit another report", "no": "No", "noise": "Noise", "other": "Other", "precisionHelp": "Without a specific date and time we can only record a report as a signal, not handle it as a complaint.", "privacy": "Your information", "privacyMore": "Technology, access and your rights", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 uses your report for building management, maintenance and handling nuisance. Authorised board members and the VvE manager handle it confidentially. The tag number is encrypted separately; the existing link to the apartment remains in the VvE records.", "privacyRights": "Contact the board with questions about access, correction, deletion or objection. Provide your reference number. The board assesses requests and may verify your identity through existing records. You may also complain to the Dutch Data Protection Authority.", "privacyStorage": "This portal retains reports for up to 180 days and unlinked signals for up to 30 days. If a case needs longer handling, the board keeps only what is necessary, for at most two years after the case is closed. The board reviews these files once a year. Working copies made by handlers fall under the same term and are deleted once the case is closed. Email alerts to handlers contain only the report reference.", "privacyTech": "GitHub hosts the website. Cloudflare provides the security check and receives the report; contents and attachments are stored encrypted. Resend delivers only an alert with the reference number to the handlers. These services also process technical connection data such as an IP address. We do not store your IP address in the report or save the form in browser storage. There is no public report listing.", "rateError": "Too many attempts. Please wait a minute and try again.", "ready": "Your report is sent securely. The board will check your tag internally.", "receiptHelp": "Once received, your report gets a random reference number. Keep it for further communication. You will not receive an automatic email.", "receivedHelp": "The board will review the report and check the tag internally. Your tag number and apartment are not displayed here.", "repeatDetails": "When / how often? (optional)", "repeated": "Has this happened before?", "safety": "Safety", "saveNumber": "Keep this reference number. Use it for correspondence instead of your tag number.", "sending": "Sending…", "serverError": "Receipt could not be confirmed. Your input is still here. Please try again later. A report may already have arrived; mention a possible duplicate if you retry.", "smoke": "Smoke / odour", "submit": "Submit report", "success": "Your report has been received", "tag": "Your tag number", "tagError": "Enter a tag number of 4–32 letters or digits, or choose an anonymous signal.", "tagHelp": "Copy the number from your tag. Leading zeroes are preserved. A previously issued, deactivated tag may still be recognised in the records.", "tagWhere": "Where do I find this number?", "tagWhereAlt": "Two tags with an arrow pointing to the code on the metal bracket, and an input field where that number is entered.", "tagWhereBody": "A code is printed on the metal bracket of your tag. Copy that number exactly, including any leading zeroes. If your tag has no code, choose the anonymous signal option instead.", "tagWhereTitle": "The number on your tag", "technical": "Technical issue", "time": "Time of the incident (optional)", "timeHelp": "Local time in Rotterdam. Enter when it happened, not when you are filling in this form.", "title": "Report confidentially to the VvE", "truthful": "I confirm that this report has been completed truthfully.", "unavailable": "This reporting form is being prepared. You can view the fields, but cannot submit a report yet.", "unknown": "I don't know", "urgent": "For leaks, breakdowns or other urgent building problems, call the VvE 24-hour breakdown service:", "yes": "Yes"},
"de":{"anonWarnBack": "Zurück, ich gebe meine Chipnummer ein", "anonWarnBody": "Ohne Chipnummer hat der Vorstand nichts, worauf er sich stützen kann: keine Abmahnung, keine Sanktion, keine Prüfung einer bestimmten Wohnung. Wir können Ihnen auch nichts fragen und nichts mitteilen. Der Hinweis wird erfasst, aber meist ändert sich nichts.", "anonWarnPrivacy": "Ihre Chipnummer wird gesondert verschlüsselt gespeichert und niemals anderen Bewohnern gezeigt. Nur befugte Vorstandsmitglieder können sie über die Verwaltung einer Wohnung zuordnen.", "anonWarnProceed": "Trotzdem anonym melden", "anonWarnTitle": "Eine anonyme Meldung ist kaum eine Meldung", "anonymous": "Ich habe keine Chipnummer und möchte nur einen anonymen Hinweis geben.", "anonymousHelp": "Ohne erkennbare Chipnummer behandeln wir die Meldung nur als anonymen Hinweis. Ein Hinweis allein ist keine Grundlage für eine Abmahnung oder Sanktion.", "attachmentHelp": "Höchstens 3 Dateien: JPG, PNG oder PDF, maximal 2 MB pro Datei. Prüfen Sie auch Dateinamen und Inhalte auf unnötige personenbezogene Daten.", "attachments": "Nachweis hinzufügen (optional)", "captcha": "Führen Sie vor dem Senden die Sicherheitsprüfung durch.", "captchaBlocked": "Die Sicherheitsprüfung konnte nicht geladen werden. Deaktivieren Sie einen Adblocker oder eine Datenschutzerweiterung für diese Seite oder verwenden Sie einen anderen Browser. Eine Meldung per E-Mail ist ebenfalls möglich.", "captchaError": "Die Sicherheitsprüfung ist abgelaufen oder fehlgeschlagen. Bitte führen Sie sie erneut durch.", "category": "Art der Meldung", "choose": "Bitte wählen", "close": "Schließen", "contact": "Der Vorstand darf mich über die bestehende VvE-Verwaltung kontaktieren.", "contactHelp": "Nur wenn der Chip zuordenbar ist. Der Vorstand nimmt über die zu Ihrer Wohnung hinterlegten Daten Kontakt auf. Nach Artikel 20 der Teilungserklärung sind Eigentümer verpflichtet, ihre Mieter und Nutzer bei der VvE anzumelden.", "damage": "Schaden", "date": "Datum des Vorfalls", "description": "Beschreibung des Vorfalls", "descriptionHelp": "Beschreiben Sie, was Sie selbst gesehen, gehört oder gerochen haben. Mindestens 20 Zeichen. Vermeiden Sie unnötige Namen und andere personenbezogene Daten. Sie dürfen in Ihrer eigenen Sprache schreiben.", "dirt": "Verschmutzung", "dur1": "Weniger als 15 Minuten", "dur2": "15 Minuten bis 1 Stunde", "dur3": "1 bis 3 Stunden", "dur4": "3 bis 6 Stunden", "dur5": "6 bis 12 Stunden", "dur6": "Mehr als 12 Stunden", "dur7": "Durchgehend, nahezu ständig", "dur8": "Dauert derzeit noch an", "duration": "Wie lange hat es gedauert?", "durationHelp": "Eine Schätzung genügt. Wählen Sie „durchgehend“, wenn es sich nicht um einen einzelnen Vorfall handelt.", "emergency": "Dieses Formular ist nicht für Notfälle. Rufen Sie bei unmittelbarer Gefahr 112 an.", "event": "2. Was ist passiert?", "fileError": "Verwenden Sie höchstens 3 JPG-, PNG- oder PDF-Dateien von je maximal 2 MB.", "followup": "3. Weiteres Vorgehen", "futureError": "Das Datum des Vorfalls darf nicht in der Zukunft liegen.", "identity": "1. Ihr Zugangschip", "intro": "Sie müssen weder Ihren Namen noch Ihre Adresse angeben. Verwenden Sie die Nummer eines für Ihre Wohnung ausgegebenen Zugangschips. Nur befugte Vorstandsmitglieder und die VvE-Verwaltung dürfen diese Nummer über die Chipverwaltung einer Wohnung zuordnen. Ihre Identität wird anderen Bewohnern nicht ohne Notwendigkeit mitgeteilt.", "invalid": "Bitte prüfen Sie die Pflichtfelder.", "location": "Ort oder betroffene Wohnung", "locationHelp": "Wo ist es passiert? Tragen Sie hier nicht Ihre eigene Adresse als Kontaktangabe ein, wenn Sie anonym bleiben möchten.", "navReport": "Problem melden", "navRules": "Gebäuderegeln", "navUpdates": "Informationen für Eigentümer", "newReport": "Eine neue Meldung machen", "no": "Nein", "noise": "Lärm", "other": "Sonstiges", "precisionHelp": "Ohne konkretes Datum und konkrete Uhrzeit können wir eine Meldung nur als Hinweis erfassen und nicht als Beschwerde behandeln.", "privacy": "Ihre Daten", "privacyMore": "Technik, Zugang und Ihre Rechte", "privacyPurpose": "Die VvE Ogierssingel 263/301 – Bollandstraat 29/35 verwendet Ihre Meldung für Verwaltung, Instandhaltung und die Bearbeitung von Belästigungen. Befugte Vorstandsmitglieder und die VvE-Verwaltung behandeln den Inhalt vertraulich. Die Chipnummer wird gesondert verschlüsselt gespeichert; die bestehende Zuordnung zur Wohnung bleibt in der VvE-Verwaltung.", "privacyRights": "Bei Fragen zu Auskunft, Berichtigung, Löschung oder Widerspruch wenden Sie sich an den Vorstand. Geben Sie Ihre Meldungsnummer an. Der Vorstand prüft den Antrag und kann Ihre Identität über die bestehende Verwaltung überprüfen. Sie können sich auch bei der niederländischen Datenschutzbehörde beschweren.", "privacyStorage": "Die Meldestelle bewahrt Meldungen höchstens 180 Tage und nicht zuordenbare Hinweise höchstens 30 Tage auf. Muss ein Fall länger bearbeitet werden, bewahrt der Vorstand nur das Notwendige auf, längstens zwei Jahre nach Abschluss des Falls. Der Vorstand sichtet diese Akten jährlich. Arbeitskopien der Bearbeiter unterliegen derselben Frist und werden nach Abschluss gelöscht. E-Mail-Benachrichtigungen an Bearbeiter enthalten nur die Meldungsnummer.", "privacyTech": "GitHub betreibt die Website. Cloudflare übernimmt die Sicherheitsprüfung und empfängt die Meldung; Inhalt und Anhänge werden verschlüsselt gespeichert. Resend stellt den Bearbeitern ausschließlich eine Nachricht mit der Meldungsnummer zu. Diese Dienste verarbeiten auch technische Verbindungsdaten wie eine IP-Adresse. Wir speichern Ihre IP-Adresse nicht in der Meldung und legen Ihr Formular nicht im Browserspeicher ab. Eine öffentliche Meldungsübersicht gibt es nicht.", "rateError": "Zu viele Versuche. Warten Sie eine Minute und versuchen Sie es erneut.", "ready": "Ihre Meldung wird gesichert übertragen. Der Vorstand prüft Ihren Chip intern.", "receiptHelp": "Nach Eingang erhalten Sie eine zufällige Meldungsnummer. Bewahren Sie diese für die weitere Kommunikation auf. Eine automatische E-Mail erhalten Sie nicht.", "receivedHelp": "Der Vorstand prüft Ihre Meldung und kontrolliert den Chip intern. Ihre Chipnummer und Ihre Wohnung werden hier nicht angezeigt.", "repeatDetails": "Wann / wie oft? (optional)", "repeated": "Ist das schon einmal vorgekommen?", "safety": "Sicherheit", "saveNumber": "Bewahren Sie diese Meldungsnummer auf. Verwenden Sie künftig diese Nummer im Schriftverkehr, nicht Ihre Chipnummer.", "sending": "Wird gesendet…", "serverError": "Der Eingang konnte nicht bestätigt werden. Ihre Eingaben stehen noch da. Bitte versuchen Sie es später erneut. Ihre Meldung kann bereits angekommen sein; weisen Sie beim erneuten Senden auf eine mögliche Doppelmeldung hin.", "smoke": "Rauch / Geruch", "submit": "Meldung absenden", "success": "Ihre Meldung ist eingegangen", "tag": "Ihre Chipnummer", "tagError": "Geben Sie eine Chipnummer aus 4–32 Buchstaben oder Ziffern ein oder wählen Sie einen anonymen Hinweis.", "tagHelp": "Übernehmen Sie die Nummer von Ihrem Chip. Führende Nullen bleiben erhalten. Ein früher ausgegebener, deaktivierter Chip kann in der Verwaltung noch erkennbar sein.", "tagWhere": "Wo finde ich diese Nummer?", "tagWhereAlt": "Zwei Chips mit einem Pfeil auf den Code am Metallbügel und ein Eingabefeld, in das diese Nummer eingetragen wird.", "tagWhereBody": "Auf dem Metallbügel Ihres Chips ist ein Code aufgedruckt. Übernehmen Sie diese Nummer genau, einschließlich führender Nullen. Steht auf Ihrem Chip kein Code, wählen Sie den anonymen Hinweis.", "tagWhereTitle": "Die Nummer auf Ihrem Chip", "technical": "Technisches Problem", "time": "Uhrzeit des Vorfalls (optional)", "timeHelp": "Ortszeit in Rotterdam. Geben Sie an, wann es passiert ist, nicht wann Sie dieses Formular ausfüllen.", "title": "Vertraulich an die VvE melden", "truthful": "Ich versichere, dass diese Meldung wahrheitsgemäß ausgefüllt ist.", "unavailable": "Dieses Meldeformular wird vorbereitet. Sie können die Felder ansehen, aber noch keine Meldung absenden.", "unknown": "Weiß ich nicht", "urgent": "Bei Wasserschäden, Störungen oder anderen dringenden Gebäudeproblemen rufen Sie den 24-Stunden-Notdienst der VvE an:", "yes": "Ja"},
"pl":{"anonWarnBack": "Wróć, podam numer breloka", "anonWarnBody": "Bez numeru breloka zarząd nie ma na czym oprzeć działania: żadnego upomnienia, żadnej sankcji, żadnego sprawdzenia konkretnego mieszkania. Nie możemy też o nic zapytać ani niczego przekazać. Sygnał zostanie zapisany, ale zwykle nic się nie zmienia.", "anonWarnPrivacy": "Twój numer breloka jest przechowywany osobno w postaci zaszyfrowanej i nigdy nie jest pokazywany innym mieszkańcom. Tylko upoważnieni członkowie zarządu mogą powiązać go z mieszkaniem na podstawie ewidencji.", "anonWarnProceed": "Mimo to zgłoś anonimowo", "anonWarnTitle": "Zgłoszenie anonimowe to prawie żadne zgłoszenie", "anonymous": "Nie mam numeru breloka i chcę przekazać wyłącznie anonimowy sygnał.", "anonymousHelp": "Bez rozpoznawalnego numeru breloka traktujemy zgłoszenie wyłącznie jako anonimowy sygnał. Sam sygnał nie jest podstawą do upomnienia ani sankcji.", "attachmentHelp": "Maksymalnie 3 pliki: JPG, PNG lub PDF, do 2 MB każdy. Sprawdź też nazwy plików i ich zawartość pod kątem zbędnych danych osobowych.", "attachments": "Dodaj dowód (opcjonalnie)", "captcha": "Przed wysłaniem ukończ kontrolę bezpieczeństwa.", "captchaBlocked": "Nie udało się wczytać kontroli bezpieczeństwa. Wyłącz blokadę reklam lub rozszerzenie prywatności dla tej strony albo użyj innej przeglądarki. Możesz też zgłosić sprawę e-mailem.", "captchaError": "Kontrola bezpieczeństwa wygasła lub się nie powiodła. Wykonaj ją ponownie.", "category": "Rodzaj zgłoszenia", "choose": "Wybierz opcję", "close": "Zamknij", "contact": "Zarząd może się ze mną skontaktować za pośrednictwem istniejącej ewidencji VvE.", "contactHelp": "Tylko jeśli brelok da się powiązać z mieszkaniem. Zarząd skontaktuje się przez dane zarejestrowane dla Twojego mieszkania. Zgodnie z artykułem 20 regulaminu podziału właściciele mają obowiązek zgłaszać swoich najemców i użytkowników do VvE.", "damage": "Uszkodzenie", "date": "Data zdarzenia", "description": "Opis zdarzenia", "descriptionHelp": "Opisz, co osobiście widziałeś, słyszałeś lub poczułeś. Co najmniej 20 znaków. Unikaj zbędnych nazwisk i innych danych osobowych. Możesz pisać we własnym języku.", "dirt": "Zanieczyszczenie", "dur1": "Krócej niż 15 minut", "dur2": "Od 15 minut do 1 godziny", "dur3": "Od 1 do 3 godzin", "dur4": "Od 3 do 6 godzin", "dur5": "Od 6 do 12 godzin", "dur6": "Dłużej niż 12 godzin", "dur7": "Ciągle, niemal bez przerwy", "dur8": "Trwa nadal w tej chwili", "duration": "Jak długo to trwało?", "durationHelp": "Szacunek wystarczy. Wybierz „ciągle”, jeśli nie chodzi o pojedyncze zdarzenie.", "emergency": "Ten formularz nie służy do zgłoszeń pilnych. W razie bezpośredniego zagrożenia dzwoń pod 112.", "event": "2. Co się wydarzyło?", "fileError": "Użyj najwyżej 3 plików JPG, PNG lub PDF, każdy nie większy niż 2 MB.", "followup": "3. Dalsze kroki", "futureError": "Data zdarzenia nie może być w przyszłości.", "identity": "1. Twój brelok dostępu", "intro": "Nie musisz podawać imienia, nazwiska ani adresu. Użyj numeru breloka dostępu wydanego dla Twojego mieszkania. Tylko upoważnieni członkowie zarządu i zarządca VvE mogą powiązać ten numer z mieszkaniem na podstawie ewidencji breloków. Twoja tożsamość nie zostanie ujawniona innym mieszkańcom bez potrzeby.", "invalid": "Sprawdź pola obowiązkowe.", "location": "Miejsce lub mieszkanie, którego dotyczy", "locationHelp": "Gdzie to się wydarzyło? Nie podawaj tutaj własnego adresu jako danych kontaktowych, jeśli chcesz pozostać anonimowy.", "navReport": "Zgłoś problem", "navRules": "Regulamin budynku", "navUpdates": "Informacje dla właścicieli", "newReport": "Wyślij nowe zgłoszenie", "no": "Nie", "noise": "Hałas", "other": "Inne", "precisionHelp": "Bez konkretnej daty i godziny możemy zarejestrować zgłoszenie wyłącznie jako sygnał i nie rozpatrzymy go jako skargi.", "privacy": "Twoje dane", "privacyMore": "Technika, dostęp i Twoje prawa", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 wykorzystuje zgłoszenie do zarządzania budynkiem, konserwacji i rozpatrywania uciążliwości. Upoważnieni członkowie zarządu i zarządca VvE traktują treść poufnie. Numer breloka przechowywany jest osobno w postaci zaszyfrowanej; istniejące powiązanie z mieszkaniem pozostaje w ewidencji VvE.", "privacyRights": "W sprawach dostępu, sprostowania, usunięcia lub sprzeciwu zwróć się do zarządu. Podaj numer zgłoszenia. Zarząd oceni wniosek i może zweryfikować Twoją tożsamość na podstawie istniejącej ewidencji. Możesz też złożyć skargę do niderlandzkiego organu ochrony danych osobowych.", "privacyStorage": "Punkt zgłoszeń przechowuje zgłoszenia najwyżej 180 dni, a sygnały bez powiązania najwyżej 30 dni. Jeśli sprawa wymaga dłuższego prowadzenia, zarząd przechowuje tylko to, co niezbędne, najdłużej dwa lata po zamknięciu sprawy. Zarząd przegląda te akta raz w roku. Kopie robocze sporządzone przez osoby prowadzące sprawę podlegają temu samemu terminowi i są usuwane po zamknięciu. Powiadomienia e-mail zawierają wyłącznie numer zgłoszenia.", "privacyTech": "GitHub udostępnia stronę. Cloudflare przeprowadza kontrolę bezpieczeństwa i odbiera zgłoszenie; treść i załączniki są przechowywane w postaci zaszyfrowanej. Resend dostarcza osobom prowadzącym wyłącznie wiadomość z numerem zgłoszenia. Usługi te przetwarzają także techniczne dane połączenia, takie jak adres IP. Nie zapisujemy Twojego adresu IP w zgłoszeniu ani nie przechowujemy formularza w pamięci przeglądarki. Nie istnieje publiczny wykaz zgłoszeń.", "rateError": "Zbyt wiele prób. Odczekaj minutę i spróbuj ponownie.", "ready": "Twoje zgłoszenie zostanie wysłane w sposób zabezpieczony. Zarząd sprawdzi brelok wewnętrznie.", "receiptHelp": "Po otrzymaniu zgłoszenia dostaniesz losowy numer zgłoszenia. Zachowaj go do dalszej korespondencji. Nie otrzymasz automatycznej wiadomości e-mail.", "receivedHelp": "Zarząd oceni zgłoszenie i wewnętrznie sprawdzi brelok. Numer breloka i mieszkanie nie są tutaj pokazywane.", "repeatDetails": "Kiedy / jak często? (opcjonalnie)", "repeated": "Czy zdarzyło się to wcześniej?", "safety": "Bezpieczeństwo", "saveNumber": "Zachowaj ten numer zgłoszenia. W korespondencji używaj odtąd tego numeru, a nie numeru breloka.", "sending": "Wysyłanie…", "serverError": "Nie udało się potwierdzić odbioru. Twoje dane nadal tu są. Spróbuj ponownie później. Zgłoszenie mogło już dotrzeć; przy ponownej próbie wspomnij o możliwym duplikacie.", "smoke": "Dym / zapach", "submit": "Wyślij zgłoszenie", "success": "Twoje zgłoszenie zostało odebrane", "tag": "Numer breloka zgłaszającego", "tagError": "Podaj numer breloka złożony z 4–32 liter lub cyfr albo wybierz anonimowy sygnał.", "tagHelp": "Przepisz numer ze swojego breloka. Zera wiodące należy zachować. Wcześniej wydany, dezaktywowany brelok może być nadal rozpoznawalny w ewidencji.", "tagWhere": "Gdzie znajdę ten numer?", "tagWhereAlt": "Dwa breloki ze strzałką wskazującą kod na metalowym zaczepie oraz pole, w które wpisuje się ten numer.", "tagWhereBody": "Na metalowym zaczepie breloka nadrukowany jest kod. Przepisz ten numer dokładnie, wraz z zerami wiodącymi. Jeśli na breloku nie ma kodu, wybierz anonimowy sygnał.", "tagWhereTitle": "Numer na Twoim breloku", "technical": "Problem techniczny", "time": "Godzina zdarzenia (opcjonalnie)", "timeHelp": "Czas lokalny w Rotterdamie. Podaj, kiedy to się wydarzyło, a nie kiedy wypełniasz formularz.", "title": "Poufne zgłoszenie do VvE", "truthful": "Oświadczam, że zgłoszenie wypełniono zgodnie z prawdą.", "unavailable": "Formularz zgłoszeniowy jest przygotowywany. Możesz obejrzeć pola, ale nie możesz jeszcze wysłać zgłoszenia.", "unknown": "Nie wiem", "urgent": "W przypadku zalania, awarii lub innych pilnych problemów z budynkiem zadzwoń na całodobowy numer awaryjny VvE:", "yes": "Tak"},
"ro":{"anonWarnBack": "Înapoi, îmi introduc numărul tagului", "anonWarnBody": "Fără numărul tagului consiliul nu are pe ce să se bazeze: niciun avertisment, nicio sancțiune, nicio verificare a unui anumit apartament. Nu vă putem nici întreba nimic, nici comunica ceva. Semnalul este înregistrat, dar de obicei nu se schimbă nimic.", "anonWarnPrivacy": "Numărul tagului este păstrat criptat separat și nu este arătat niciodată altor locatari. Numai membrii autorizați ai consiliului îl pot lega de un apartament prin evidență.", "anonWarnProceed": "Continuă totuși anonim", "anonWarnTitle": "O raportare anonimă este aproape nicio raportare", "anonymous": "Nu am număr de tag și vreau să transmit doar un semnal anonim.", "anonymousHelp": "Fără un număr de tag recognoscibil, tratăm raportarea doar ca semnal anonim. Un semnal singur nu constituie temei pentru avertisment sau sancțiune.", "attachmentHelp": "Maximum 3 fișiere: JPG, PNG sau PDF, cel mult 2 MB fiecare. Verificați și denumirile și conținutul fișierelor pentru date personale inutile.", "attachments": "Adăugați dovezi (opțional)", "captcha": "Finalizați verificarea de securitate înainte de trimitere.", "captchaBlocked": "Verificarea de securitate nu a putut fi încărcată. Dezactivați blocarea reclamelor sau extensia de confidențialitate pentru această pagină ori încercați alt browser. Puteți raporta și prin e-mail.", "captchaError": "Verificarea de securitate a expirat sau a eșuat. Efectuați-o din nou.", "category": "Tipul raportării", "choose": "Alegeți o opțiune", "close": "Închide", "contact": "Consiliul poate să mă contacteze prin evidența existentă a VvE.", "contactHelp": "Numai dacă tagul poate fi asociat unui apartament. Consiliul va lua legătura folosind datele înregistrate pentru apartamentul dumneavoastră. Conform articolului 20 din regulamentul de partajare, proprietarii sunt obligați să își înregistreze chiriașii și utilizatorii la VvE.", "damage": "Daune", "date": "Data incidentului", "description": "Descrierea incidentului", "descriptionHelp": "Descrieți ce ați văzut, auzit sau mirosit personal. Minimum 20 de caractere. Evitați numele inutile și alte date personale. Puteți scrie în limba dumneavoastră.", "dirt": "Murdărie", "dur1": "Mai puțin de 15 minute", "dur2": "Între 15 minute și 1 oră", "dur3": "Între 1 și 3 ore", "dur4": "Între 3 și 6 ore", "dur5": "Între 6 și 12 ore", "dur6": "Peste 12 ore", "dur7": "Continuu, aproape fără întrerupere", "dur8": "Continuă și în acest moment", "duration": "Cât a durat?", "durationHelp": "O estimare este suficientă. Alegeți „continuu” dacă nu este vorba de un incident izolat.", "emergency": "Acest formular nu este pentru urgențe. Sunați la 112 în caz de pericol imediat.", "event": "2. Ce s-a întâmplat?", "fileError": "Folosiți cel mult 3 fișiere JPG, PNG sau PDF, fiecare de maximum 2 MB.", "followup": "3. Urmărire", "futureError": "Data incidentului nu poate fi în viitor.", "identity": "1. Tagul dumneavoastră de acces", "intro": "Nu trebuie să vă indicați numele sau adresa. Folosiți numărul unui tag de acces emis pentru apartamentul dumneavoastră. Numai membrii autorizați ai consiliului și administratorul VvE pot lega acest număr de un apartament prin evidența tagurilor. Identitatea dumneavoastră nu va fi dezvăluită altor locatari fără necesitate.", "invalid": "Verificați câmpurile obligatorii.", "location": "Locul sau apartamentul implicat", "locationHelp": "Unde s-a întâmplat? Nu introduceți aici propria adresă ca date de contact dacă doriți să rămâneți anonim.", "navReport": "Raportează o problemă", "navRules": "Regulamentul clădirii", "navUpdates": "Informații pentru proprietari", "newReport": "Trimite o nouă raportare", "no": "Nu", "noise": "Zgomot", "other": "Altele", "precisionHelp": "Fără o dată și o oră concrete putem înregistra raportarea doar ca semnal, nu o putem trata ca plângere.", "privacy": "Datele dumneavoastră", "privacyMore": "Tehnologie, acces și drepturile dumneavoastră", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 folosește raportarea pentru administrare, întreținere și tratarea neplăcerilor. Membrii autorizați ai consiliului și administratorul VvE tratează conținutul confidențial. Numărul tagului este păstrat criptat separat; legătura existentă cu apartamentul rămâne în evidența VvE.", "privacyRights": "Pentru întrebări privind accesul, rectificarea, ștergerea sau opoziția, adresați-vă consiliului. Indicați numărul raportării. Consiliul evaluează cererea și vă poate verifica identitatea prin evidența existentă. Puteți depune și o plângere la autoritatea neerlandeză pentru protecția datelor.", "privacyStorage": "Ghișeul păstrează raportările cel mult 180 de zile, iar semnalele neasociate cel mult 30 de zile. Dacă un caz necesită tratare mai îndelungată, consiliul păstrează doar ce este necesar, cel mult doi ani după închiderea cazului. Consiliul revizuiește aceste dosare anual. Copiile de lucru intră sub același termen și sunt șterse după închidere. Notificările prin e-mail conțin doar numărul raportării.", "privacyTech": "GitHub găzduiește site-ul. Cloudflare asigură verificarea de securitate și primește raportarea; conținutul și atașamentele sunt stocate criptat. Resend livrează doar un mesaj cu numărul raportării. Aceste servicii prelucrează și date tehnice de conexiune, precum adresa IP. Nu păstrăm adresa dumneavoastră IP în raportare și nu salvăm formularul în memoria browserului. Nu există o listă publică a raportărilor.", "rateError": "Prea multe încercări. Așteptați un minut și încercați din nou.", "ready": "Raportarea dumneavoastră este trimisă securizat. Consiliul va verifica tagul intern.", "receiptHelp": "După primire veți primi un număr de raportare aleatoriu. Păstrați-l pentru corespondența ulterioară. Nu veți primi un e-mail automat.", "receivedHelp": "Consiliul va evalua raportarea și va verifica tagul intern. Numărul tagului și apartamentul nu sunt afișate aici.", "repeatDetails": "Când / cât de des? (opțional)", "repeated": "S-a mai întâmplat înainte?", "safety": "Siguranță", "saveNumber": "Păstrați acest număr de raportare. Folosiți de acum acest număr în corespondență, nu numărul tagului.", "sending": "Se trimite…", "serverError": "Primirea nu a putut fi confirmată. Datele introduse sunt încă aici. Încercați din nou mai târziu. Raportarea poate să fi ajuns deja; menționați o posibilă dublură dacă reîncercați.", "smoke": "Fum / miros", "submit": "Trimite raportarea", "success": "Raportarea dumneavoastră a fost primită", "tag": "Numărul tagului", "tagError": "Introduceți un număr de tag de 4–32 de litere sau cifre, ori alegeți un semnal anonim.", "tagHelp": "Copiați numărul de pe tag. Zerourile de la început se păstrează. Un tag emis anterior și dezactivat poate fi încă recunoscut în evidență.", "tagWhere": "Unde găsesc acest număr?", "tagWhereAlt": "Două taguri cu o săgeată care indică codul de pe brățara metalică și un câmp în care se introduce acel număr.", "tagWhereBody": "Pe brățara metalică a tagului este imprimat un cod. Copiați exact acel număr, inclusiv zerourile de la început. Dacă tagul nu are cod, alegeți semnalul anonim.", "tagWhereTitle": "Numărul de pe tagul dumneavoastră", "technical": "Problemă tehnică", "time": "Ora incidentului (opțional)", "timeHelp": "Ora locală din Rotterdam. Indicați când s-a întâmplat, nu când completați formularul.", "title": "Raportare confidențială către VvE", "truthful": "Declar că această raportare a fost completată conform adevărului.", "unavailable": "Formularul de raportare este în pregătire. Puteți vedea câmpurile, dar încă nu puteți trimite o raportare.", "unknown": "Nu știu", "urgent": "Pentru scurgeri, defecțiuni sau alte probleme urgente ale clădirii, sunați la serviciul de avarii non-stop al VvE:", "yes": "Da"},
"bg":{"anonWarnBack": "Назад, ще въведа номера на чипа си", "anonWarnBody": "Без номер на чип управата няма на какво да стъпи: нито предупреждение, нито санкция, нито проверка на конкретен апартамент. Не можем и да ви питаме нищо, нито да ви уведомим. Сигналът се записва, но обикновено нищо не се променя.", "anonWarnPrivacy": "Номерът на вашия чип се съхранява отделно в криптиран вид и никога не се показва на други живущи. Само упълномощени членове на управата могат да го свържат с апартамент чрез регистъра.", "anonWarnProceed": "Все пак подай анонимно", "anonWarnTitle": "Анонимният сигнал е почти никакъв сигнал", "anonymous": "Нямам номер на чип и искам да подам само анонимен сигнал.", "anonymousHelp": "Без разпознаваем номер на чип разглеждаме сигнала само като анонимен. Само сигнал не е основание за предупреждение или санкция.", "attachmentHelp": "Най-много 3 файла: JPG, PNG или PDF, до 2 MB всеки. Проверете и имената и съдържанието на файловете за ненужни лични данни.", "attachments": "Добавете доказателство (по избор)", "captcha": "Завършете проверката за сигурност преди изпращане.", "captchaBlocked": "Проверката за сигурност не можа да се зареди. Изключете блокиращо реклами или разширение за поверителност за тази страница или опитайте с друг браузър. Може да подадете сигнал и по имейл.", "captchaError": "Проверката за сигурност изтече или не бе успешна. Извършете я отново.", "category": "Вид сигнал", "choose": "Изберете", "close": "Затвори", "contact": "Управата може да се свърже с мен чрез съществуващия регистър на VvE.", "contactHelp": "Само ако чипът може да бъде свързан с апартамент. Управата ще се свърже чрез данните, вписани за вашия апартамент. Съгласно член 20 от правилника за разделяне собствениците са длъжни да регистрират своите наематели и ползватели при VvE.", "damage": "Щети", "date": "Дата на случката", "description": "Описание на случката", "descriptionHelp": "Опишете какво лично сте видели, чули или подушили. Най-малко 20 знака. Избягвайте ненужни имена и други лични данни. Можете да пишете на своя език.", "dirt": "Замърсяване", "dur1": "По-малко от 15 минути", "dur2": "От 15 минути до 1 час", "dur3": "От 1 до 3 часа", "dur4": "От 3 до 6 часа", "dur5": "От 6 до 12 часа", "dur6": "Повече от 12 часа", "dur7": "Непрекъснато, почти постоянно", "dur8": "Продължава и в момента", "duration": "Колко продължи?", "durationHelp": "Приблизителна преценка е достатъчна. Изберете „непрекъснато“, ако не става дума за единичен случай.", "emergency": "Този формуляр не е за спешни случаи. При непосредствена опасност се обадете на 112.", "event": "2. Какво се случи?", "fileError": "Използвайте най-много 3 файла JPG, PNG или PDF, всеки до 2 MB.", "followup": "3. Последващи действия", "futureError": "Датата на случката не може да е в бъдещето.", "identity": "1. Вашият чип за достъп", "intro": "Не е необходимо да посочвате име или адрес. Използвайте номера на чип за достъп, издаден за вашия апартамент. Само упълномощени членове на управата и управителят на VvE могат да свържат този номер с апартамент чрез регистъра на чиповете. Самоличността ви няма да бъде разкривана на други живущи без необходимост.", "invalid": "Проверете задължителните полета.", "location": "Място или засегнат апартамент", "locationHelp": "Къде се случи? Не въвеждайте тук собствения си адрес като данни за контакт, ако искате да останете анонимни.", "navReport": "Подайте сигнал", "navRules": "Правила на сградата", "navUpdates": "Информация за собствениците", "newReport": "Подаване на нов сигнал", "no": "Не", "noise": "Шум", "other": "Друго", "precisionHelp": "Без конкретна дата и час можем да отбележим сигнала само като сигнал и не можем да го разгледаме като оплакване.", "privacy": "Вашите данни", "privacyMore": "Технологии, достъп и вашите права", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 използва сигнала за управление, поддръжка и разглеждане на смущения. Упълномощени членове на управата и управителят на VvE третират съдържанието поверително. Номерът на чипа се съхранява отделно в криптиран вид; съществуващата връзка с апартамента остава в регистъра на VvE.", "privacyRights": "За въпроси относно достъп, поправка, изтриване или възражение се обърнете към управата. Посочете номера на сигнала. Управата преценява искането и може да провери самоличността ви чрез съществуващия регистър. Можете да подадете жалба и до нидерландския орган за защита на данните.", "privacyStorage": "Гишето съхранява сигналите най-много 180 дни, а несвързаните сигнали най-много 30 дни. Ако случай изисква по-дълго разглеждане, управата пази само необходимото, най-много две години след приключване на случая. Управата преглежда тези досиета веднъж годишно. Работните копия попадат под същия срок и се изтриват след приключване. Имейл известията съдържат само номера на сигнала.", "privacyTech": "GitHub хоства уебсайта. Cloudflare извършва проверката за сигурност и получава сигнала; съдържанието и прикачените файлове се съхраняват криптирани. Resend доставя само съобщение с номера на сигнала. Тези услуги обработват и технически данни за връзката, например IP адрес. Не съхраняваме вашия IP адрес в сигнала и не запазваме формуляра в паметта на браузъра. Няма публичен списък със сигнали.", "rateError": "Твърде много опити. Изчакайте минута и опитайте отново.", "ready": "Сигналът ви се изпраща защитено. Управата ще провери чипа вътрешно.", "receiptHelp": "След получаване ще получите случаен номер на сигнала. Запазете го за по-нататъшна кореспонденция. Няма да получите автоматичен имейл.", "receivedHelp": "Управата ще разгледа сигнала и ще провери чипа вътрешно. Номерът на чипа и апартаментът не се показват тук.", "repeatDetails": "Кога / колко често? (по избор)", "repeated": "Случвало ли се е и преди?", "safety": "Безопасност", "saveNumber": "Запазете този номер на сигнала. Отсега използвайте този номер в кореспонденцията, а не номера на чипа.", "sending": "Изпраща се…", "serverError": "Получаването не можа да бъде потвърдено. Въведеното все още е тук. Опитайте отново по-късно. Сигналът може вече да е пристигнал; при повторен опит споменете евентуално дублиране.", "smoke": "Дим / миризма", "submit": "Изпрати сигнала", "success": "Вашият сигнал е получен", "tag": "Номер на чипа на подателя", "tagError": "Въведете номер на чип от 4–32 букви или цифри, или изберете анонимен сигнал.", "tagHelp": "Препишете номера от вашия чип. Водещите нули се запазват. По-рано издаден, деактивиран чип може все още да се разпознае в регистъра.", "tagWhere": "Къде да намеря този номер?", "tagWhereAlt": "Два чипа със стрелка към кода върху металната скоба и поле, в което се въвежда този номер.", "tagWhereBody": "Върху металната скоба на чипа е отпечатан код. Препишете този номер точно, включително водещите нули. Ако върху чипа няма код, изберете анонимен сигнал.", "tagWhereTitle": "Номерът върху вашия чип", "technical": "Технически проблем", "time": "Час на случката (по избор)", "timeHelp": "Местно време в Ротердам. Посочете кога се е случило, а не кога попълвате формуляра.", "title": "Поверителен сигнал до VvE", "truthful": "Декларирам, че сигналът е попълнен добросъвестно.", "unavailable": "Формулярът за сигнали се подготвя. Можете да разгледате полетата, но още не можете да изпратите сигнал.", "unknown": "Не знам", "urgent": "При течове, аварии или други спешни проблеми със сградата се обадете на денонощната аварийна служба на VvE:", "yes": "Да"},
"cs":{"anonWarnBack": "Zpět, zadám číslo čipu", "anonWarnBody": "Bez čísla čipu nemá výbor o co se opřít: žádná výstraha, žádná sankce, žádné prověření konkrétního bytu. Nemůžeme se vás také na nic zeptat ani vám nic sdělit. Podnět se zaznamená, ale obvykle se nic nezmění.", "anonWarnPrivacy": "Číslo vašeho čipu se uchovává odděleně v zašifrované podobě a nikdy se nezobrazuje ostatním obyvatelům. Přiřadit je k bytu mohou přes evidenci jen pověření členové výboru.", "anonWarnProceed": "Přesto nahlásit anonymně", "anonWarnTitle": "Anonymní hlášení je téměř žádné hlášení", "anonymous": "Nemám číslo čipu a chci předat pouze anonymní podnět.", "anonymousHelp": "Bez rozpoznatelného čísla čipu považujeme hlášení pouze za anonymní podnět. Samotný podnět není důvodem k výstraze ani sankci.", "attachmentHelp": "Nejvýše 3 soubory: JPG, PNG nebo PDF, každý do 2 MB. Zkontrolujte také názvy a obsah souborů kvůli zbytečným osobním údajům.", "attachments": "Přidat důkaz (nepovinné)", "captcha": "Před odesláním dokončete bezpečnostní kontrolu.", "captchaBlocked": "Bezpečnostní kontrolu se nepodařilo načíst. Vypněte pro tuto stránku blokování reklam nebo rozšíření na ochranu soukromí, případně zkuste jiný prohlížeč. Nahlásit lze i e-mailem.", "captchaError": "Bezpečnostní kontrola vypršela nebo se nezdařila. Proveďte ji znovu.", "category": "Druh hlášení", "choose": "Vyberte možnost", "close": "Zavřít", "contact": "Výbor mě může kontaktovat prostřednictvím stávající evidence VvE.", "contactHelp": "Pouze pokud lze čip přiřadit k bytu. Výbor vás kontaktuje pomocí údajů evidovaných k vašemu bytu. Podle článku 20 prohlášení o rozdělení jsou vlastníci povinni přihlásit své nájemce a uživatele u VvE.", "damage": "Škoda", "date": "Datum události", "description": "Popis události", "descriptionHelp": "Popište, co jste sami viděli, slyšeli nebo cítili. Nejméně 20 znaků. Vyhněte se zbytečným jménům a jiným osobním údajům. Můžete psát ve svém jazyce.", "dirt": "Znečištění", "dur1": "Méně než 15 minut", "dur2": "15 minut až 1 hodina", "dur3": "1 až 3 hodiny", "dur4": "3 až 6 hodin", "dur5": "6 až 12 hodin", "dur6": "Více než 12 hodin", "dur7": "Průběžně, téměř nepřetržitě", "dur8": "Trvá i v tuto chvíli", "duration": "Jak dlouho to trvalo?", "durationHelp": "Stačí odhad. Zvolte „průběžně“, pokud nejde o jednotlivou událost.", "emergency": "Tento formulář není určen pro naléhavé případy. Při bezprostředním nebezpečí volejte 112.", "event": "2. Co se stalo?", "fileError": "Použijte nejvýše 3 soubory JPG, PNG nebo PDF, každý do 2 MB.", "followup": "3. Další postup", "futureError": "Datum události nemůže být v budoucnosti.", "identity": "1. Váš přístupový čip", "intro": "Nemusíte uvádět jméno ani adresu. Použijte číslo přístupového čipu vydaného pro váš byt. Pouze pověření členové výboru a správce VvE mohou toto číslo přiřadit k bytu prostřednictvím evidence čipů. Vaše totožnost nebude bez nutnosti sdělena ostatním obyvatelům.", "invalid": "Zkontrolujte povinná pole.", "location": "Místo nebo dotčený byt", "locationHelp": "Kde se to stalo? Neuvádějte zde vlastní adresu jako kontaktní údaj, pokud chcete zůstat v anonymitě.", "navReport": "Nahlásit problém", "navRules": "Pravidla budovy", "navUpdates": "Informace pro vlastníky", "newReport": "Podat nové hlášení", "no": "Ne", "noise": "Hluk", "other": "Jiné", "precisionHelp": "Bez konkrétního data a času můžeme hlášení zaznamenat pouze jako podnět a nemůžeme je řešit jako stížnost.", "privacy": "Vaše údaje", "privacyMore": "Technika, přístup a vaše práva", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 používá vaše hlášení ke správě, údržbě a řešení obtěžování. Pověření členové výboru a správce VvE nakládají s obsahem důvěrně. Číslo čipu je uchováváno odděleně v zašifrované podobě; stávající vazba na byt zůstává v evidenci VvE.", "privacyRights": "S dotazy na přístup, opravu, výmaz nebo námitku se obraťte na výbor. Uveďte číslo hlášení. Výbor žádost posoudí a může ověřit vaši totožnost pomocí stávající evidence. Stížnost můžete podat i u nizozemského úřadu pro ochranu osobních údajů.", "privacyStorage": "Přepážka uchovává hlášení nejvýše 180 dní a nepřiřaditelné podněty nejvýše 30 dní. Pokud případ vyžaduje delší řešení, výbor uchovává jen to nezbytné, nejdéle dva roky po uzavření případu. Výbor tyto spisy jednou ročně pročišťuje. Pracovní kopie spadají pod stejnou lhůtu a po uzavření se mažou. E-mailová upozornění obsahují pouze číslo hlášení.", "privacyTech": "Web provozuje GitHub. Cloudflare zajišťuje bezpečnostní kontrolu a přijímá hlášení; obsah i přílohy jsou uloženy zašifrovaně. Resend doručuje pouze zprávu s číslem hlášení. Tyto služby zpracovávají i technické údaje o připojení, například IP adresu. Vaši IP adresu v hlášení neuchováváme a formulář neukládáme do úložiště prohlížeče. Veřejný přehled hlášení neexistuje.", "rateError": "Příliš mnoho pokusů. Počkejte minutu a zkuste to znovu.", "ready": "Vaše hlášení se odesílá zabezpečeně. Výbor ověří váš čip interně.", "receiptHelp": "Po přijetí obdržíte náhodné číslo hlášení. Uschovejte je pro další komunikaci. Automatický e-mail neobdržíte.", "receivedHelp": "Výbor hlášení posoudí a čip ověří interně. Číslo čipu ani byt se zde nezobrazují.", "repeatDetails": "Kdy / jak často? (nepovinné)", "repeated": "Stalo se to už dříve?", "safety": "Bezpečnost", "saveNumber": "Uschovejte toto číslo hlášení. V korespondenci nadále používejte toto číslo, nikoli číslo čipu.", "sending": "Odesílá se…", "serverError": "Přijetí nebylo možné potvrdit. Vaše údaje tu stále jsou. Zkuste to prosím později. Hlášení už mohlo dorazit; při opakování uveďte možnou duplicitu.", "smoke": "Kouř / zápach", "submit": "Odeslat hlášení", "success": "Vaše hlášení bylo přijato", "tag": "Číslo čipu ohlašovatele", "tagError": "Zadejte číslo čipu o 4–32 písmenech nebo číslicích, nebo zvolte anonymní podnět.", "tagHelp": "Opište číslo ze svého čipu. Úvodní nuly zůstávají zachovány. Dříve vydaný, deaktivovaný čip může být v evidenci stále rozpoznatelný.", "tagWhere": "Kde toto číslo najdu?", "tagWhereAlt": "Dva čipy se šipkou ukazující na kód na kovovém úchytu a pole, do kterého se toto číslo zadává.", "tagWhereBody": "Na kovovém úchytu čipu je vytištěn kód. Opište toto číslo přesně, včetně úvodních nul. Pokud na čipu kód není, zvolte anonymní podnět.", "tagWhereTitle": "Číslo na vašem čipu", "technical": "Technický problém", "time": "Čas události (nepovinné)", "timeHelp": "Místní čas v Rotterdamu. Uveďte, kdy se to stalo, nikoli kdy vyplňujete formulář.", "title": "Důvěrné hlášení pro VvE", "truthful": "Prohlašuji, že toto hlášení bylo vyplněno pravdivě.", "unavailable": "Formulář pro hlášení se připravuje. Pole si můžete prohlédnout, ale hlášení zatím nelze odeslat.", "unknown": "Nevím", "urgent": "Při úniku vody, poruše nebo jiných naléhavých problémech s budovou volejte nepřetržitou poruchovou službu VvE:", "yes": "Ano"},
"sk":{"anonWarnBack": "Späť, zadám číslo čipu", "anonWarnBody": "Bez čísla čipu nemá výbor o čo sa oprieť: žiadna výstraha, žiadna sankcia, žiadne preverenie konkrétneho bytu. Nemôžeme sa vás ani na nič spýtať, ani vám nič oznámiť. Podnet sa zaznamená, ale zvyčajne sa nič nezmení.", "anonWarnPrivacy": "Číslo vášho čipu sa uchováva oddelene v zašifrovanej podobe a nikdy sa nezobrazuje ostatným obyvateľom. Priradiť ho k bytu môžu cez evidenciu len poverení členovia výboru.", "anonWarnProceed": "Napriek tomu nahlásiť anonymne", "anonWarnTitle": "Anonymné hlásenie je takmer žiadne hlásenie", "anonymous": "Nemám číslo čipu a chcem odovzdať iba anonymný podnet.", "anonymousHelp": "Bez rozpoznateľného čísla čipu považujeme hlásenie iba za anonymný podnet. Samotný podnet nie je dôvodom na výstrahu ani sankciu.", "attachmentHelp": "Najviac 3 súbory: JPG, PNG alebo PDF, každý do 2 MB. Skontrolujte aj názvy a obsah súborov kvôli zbytočným osobným údajom.", "attachments": "Pridať dôkaz (nepovinné)", "captcha": "Pred odoslaním dokončite bezpečnostnú kontrolu.", "captchaBlocked": "Bezpečnostnú kontrolu sa nepodarilo načítať. Vypnite pre túto stránku blokovanie reklám alebo rozšírenie na ochranu súkromia, prípadne skúste iný prehliadač. Nahlásiť možno aj e-mailom.", "captchaError": "Bezpečnostná kontrola vypršala alebo sa nepodarila. Vykonajte ju znova.", "category": "Druh hlásenia", "choose": "Vyberte možnosť", "close": "Zavrieť", "contact": "Výbor ma môže kontaktovať prostredníctvom existujúcej evidencie VvE.", "contactHelp": "Iba ak možno čip priradiť k bytu. Výbor vás kontaktuje pomocou údajov evidovaných k vášmu bytu. Podľa článku 20 vyhlásenia o rozdelení sú vlastníci povinní prihlásiť svojich nájomcov a užívateľov u VvE.", "damage": "Škoda", "date": "Dátum udalosti", "description": "Opis udalosti", "descriptionHelp": "Opíšte, čo ste sami videli, počuli alebo cítili. Najmenej 20 znakov. Vyhnite sa zbytočným menám a iným osobným údajom. Môžete písať vo svojom jazyku.", "dirt": "Znečistenie", "dur1": "Menej než 15 minút", "dur2": "15 minút až 1 hodina", "dur3": "1 až 3 hodiny", "dur4": "3 až 6 hodín", "dur5": "6 až 12 hodín", "dur6": "Viac než 12 hodín", "dur7": "Priebežne, takmer nepretržite", "dur8": "Trvá aj v tejto chvíli", "duration": "Ako dlho to trvalo?", "durationHelp": "Stačí odhad. Zvoľte „priebežne“, ak nejde o jednotlivú udalosť.", "emergency": "Tento formulár nie je určený pre naliehavé prípady. Pri bezprostrednom nebezpečenstve volajte 112.", "event": "2. Čo sa stalo?", "fileError": "Použite najviac 3 súbory JPG, PNG alebo PDF, každý do 2 MB.", "followup": "3. Ďalší postup", "futureError": "Dátum udalosti nemôže byť v budúcnosti.", "identity": "1. Váš prístupový čip", "intro": "Nemusíte uvádzať meno ani adresu. Použite číslo prístupového čipu vydaného pre váš byt. Iba poverení členovia výboru a správca VvE môžu toto číslo priradiť k bytu cez evidenciu čipov. Vaša totožnosť nebude bez nutnosti oznámená ostatným obyvateľom.", "invalid": "Skontrolujte povinné polia.", "location": "Miesto alebo dotknutý byt", "locationHelp": "Kde sa to stalo? Neuvádzajte tu vlastnú adresu ako kontaktný údaj, ak chcete zostať v anonymite.", "navReport": "Nahlásiť problém", "navRules": "Pravidlá budovy", "navUpdates": "Informácie pre vlastníkov", "newReport": "Podať nové hlásenie", "no": "Nie", "noise": "Hluk", "other": "Iné", "precisionHelp": "Bez konkrétneho dátumu a času môžeme hlásenie zaznamenať iba ako podnet a nemôžeme ho riešiť ako sťažnosť.", "privacy": "Vaše údaje", "privacyMore": "Technika, prístup a vaše práva", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 používa vaše hlásenie na správu, údržbu a riešenie obťažovania. Poverení členovia výboru a správca VvE nakladajú s obsahom dôverne. Číslo čipu sa uchováva oddelene v zašifrovanej podobe; existujúca väzba na byt zostáva v evidencii VvE.", "privacyRights": "S otázkami na prístup, opravu, výmaz alebo námietku sa obráťte na výbor. Uveďte číslo hlásenia. Výbor žiadosť posúdi a môže overiť vašu totožnosť pomocou existujúcej evidencie. Sťažnosť môžete podať aj na holandskom úrade na ochranu osobných údajov.", "privacyStorage": "Priehradka uchováva hlásenia najviac 180 dní a nepriraditeľné podnety najviac 30 dní. Ak si prípad vyžaduje dlhšie riešenie, výbor uchováva len to nevyhnutné, najdlhšie dva roky po uzavretí prípadu. Výbor tieto spisy raz ročne prečisťuje. Pracovné kópie spadajú pod rovnakú lehotu a po uzavretí sa mažú. E-mailové upozornenia obsahujú iba číslo hlásenia.", "privacyTech": "Web prevádzkuje GitHub. Cloudflare zabezpečuje bezpečnostnú kontrolu a prijíma hlásenie; obsah aj prílohy sú uložené zašifrovane. Resend doručuje iba správu s číslom hlásenia. Tieto služby spracúvajú aj technické údaje o pripojení, napríklad IP adresu. Vašu IP adresu v hlásení neuchovávame a formulár neukladáme do úložiska prehliadača. Verejný prehľad hlásení neexistuje.", "rateError": "Príliš veľa pokusov. Počkajte minútu a skúste to znova.", "ready": "Vaše hlásenie sa odosiela zabezpečene. Výbor overí váš čip interne.", "receiptHelp": "Po prijatí dostanete náhodné číslo hlásenia. Uschovajte ho na ďalšiu komunikáciu. Automatický e-mail nedostanete.", "receivedHelp": "Výbor hlásenie posúdi a čip overí interne. Číslo čipu ani byt sa tu nezobrazujú.", "repeatDetails": "Kedy / ako často? (nepovinné)", "repeated": "Stalo sa to už predtým?", "safety": "Bezpečnosť", "saveNumber": "Uschovajte toto číslo hlásenia. V korešpondencii naďalej používajte toto číslo, nie číslo čipu.", "sending": "Odosiela sa…", "serverError": "Prijatie sa nepodarilo potvrdiť. Vaše údaje tu stále sú. Skúste to prosím neskôr. Hlásenie už mohlo doraziť; pri opakovaní uveďte možnú duplicitu.", "smoke": "Dym / zápach", "submit": "Odoslať hlásenie", "success": "Vaše hlásenie bolo prijaté", "tag": "Číslo čipu ohlasovateľa", "tagError": "Zadajte číslo čipu so 4–32 písmenami alebo číslicami, alebo zvoľte anonymný podnet.", "tagHelp": "Odpíšte číslo zo svojho čipu. Úvodné nuly zostávajú zachované. Skôr vydaný, deaktivovaný čip môže byť v evidencii stále rozpoznateľný.", "tagWhere": "Kde toto číslo nájdem?", "tagWhereAlt": "Dva čipy so šípkou ukazujúcou na kód na kovovom úchyte a pole, do ktorého sa toto číslo zadáva.", "tagWhereBody": "Na kovovom úchyte čipu je vytlačený kód. Odpíšte toto číslo presne, vrátane úvodných núl. Ak na čipe kód nie je, zvoľte anonymný podnet.", "tagWhereTitle": "Číslo na vašom čipe", "technical": "Technický problém", "time": "Čas udalosti (nepovinné)", "timeHelp": "Miestny čas v Rotterdame. Uveďte, kedy sa to stalo, nie kedy vypĺňate formulár.", "title": "Dôverné hlásenie pre VvE", "truthful": "Vyhlasujem, že toto hlásenie bolo vyplnené pravdivo.", "unavailable": "Formulár na hlásenie sa pripravuje. Polia si môžete pozrieť, ale hlásenie zatiaľ nemožno odoslať.", "unknown": "Neviem", "urgent": "Pri úniku vody, poruche alebo iných naliehavých problémoch s budovou volajte nepretržitú poruchovú službu VvE:", "yes": "Áno"},
"hu":{"anonWarnBack": "Vissza, megadom a chipszámomat", "anonWarnBody": "Chipszám nélkül a vezetőségnek nincs mire alapoznia: se figyelmeztetés, se szankció, se egy adott lakás kivizsgálása. Kérdezni sem tudunk semmit, és tájékoztatni sem tudjuk Önt. A jelzést rögzítjük, de általában nem változik semmi.", "anonWarnPrivacy": "A chipszámát külön, titkosítva tároljuk, és soha nem mutatjuk meg más lakóknak. Lakáshoz csak az arra jogosult vezetőségi tagok köthetik a nyilvántartás alapján.", "anonWarnProceed": "Mégis névtelenül küldöm", "anonWarnTitle": "A névtelen bejelentés alig bejelentés", "anonymous": "Nincs chipszámom, és kizárólag névtelen jelzést szeretnék tenni.", "anonymousHelp": "Felismerhető chipszám nélkül a bejelentést kizárólag névtelen jelzésként kezeljük. Önmagában egy jelzés nem alapja figyelmeztetésnek vagy szankciónak.", "attachmentHelp": "Legfeljebb 3 fájl: JPG, PNG vagy PDF, fájlonként legfeljebb 2 MB. Ellenőrizze a fájlneveket és a tartalmat is szükségtelen személyes adatok szempontjából.", "attachments": "Bizonyíték csatolása (nem kötelező)", "captcha": "Küldés előtt végezze el a biztonsági ellenőrzést.", "captchaBlocked": "A biztonsági ellenőrzést nem sikerült betölteni. Kapcsolja ki a reklámblokkolót vagy az adatvédelmi bővítményt ezen az oldalon, vagy próbáljon másik böngészőt. Bejelentést e-mailben is tehet.", "captchaError": "A biztonsági ellenőrzés lejárt vagy nem sikerült. Végezze el újra.", "category": "A bejelentés típusa", "choose": "Válasszon", "close": "Bezárás", "contact": "A vezetőség felveheti velem a kapcsolatot a meglévő VvE-nyilvántartás alapján.", "contactHelp": "Csak ha a chip lakáshoz köthető. A vezetőség a lakásához nyilvántartott adatok alapján veszi fel a kapcsolatot. A társasházi alapító okirat 20. cikke szerint a tulajdonosok kötelesek bejelenteni bérlőiket és használóikat a VvE-nél.", "damage": "Kár", "date": "Az esemény dátuma", "description": "Az esemény leírása", "descriptionHelp": "Írja le, mit látott, hallott vagy érzett személyesen. Legalább 20 karakter. Kerülje a szükségtelen neveket és egyéb személyes adatokat. Írhat a saját nyelvén.", "dirt": "Szennyeződés", "dur1": "Kevesebb mint 15 perc", "dur2": "15 perctől 1 óráig", "dur3": "1–3 óra", "dur4": "3–6 óra", "dur5": "6–12 óra", "dur6": "Több mint 12 óra", "dur7": "Folyamatosan, szinte megszakítás nélkül", "dur8": "Jelenleg is tart", "duration": "Meddig tartott?", "durationHelp": "A becslés is elegendő. Válassza a „folyamatosan” lehetőséget, ha nem egyszeri esetről van szó.", "emergency": "Ez az űrlap nem sürgős esetekre való. Közvetlen veszély esetén hívja a 112-t.", "event": "2. Mi történt?", "fileError": "Legfeljebb 3 JPG-, PNG- vagy PDF-fájlt használjon, egyenként legfeljebb 2 MB méretben.", "followup": "3. További intézkedés", "futureError": "Az esemény dátuma nem lehet a jövőben.", "identity": "1. Az Ön beléptető chipje", "intro": "Nem kell megadnia a nevét vagy a címét. Használja a lakásához kiadott beléptető chip számát. Ezt a számot csak az arra jogosult vezetőségi tagok és a VvE-kezelő kapcsolhatja lakáshoz a chipnyilvántartás alapján. Személyazonosságát szükségtelenül nem hozzuk más lakók tudomására.", "invalid": "Ellenőrizze a kötelező mezőket.", "location": "Helyszín vagy érintett lakás", "locationHelp": "Hol történt? Ne írja ide a saját címét kapcsolattartási adatként, ha névtelen szeretne maradni.", "navReport": "Probléma bejelentése", "navRules": "Házirend", "navUpdates": "Tulajdonosi tájékoztató", "newReport": "Új bejelentés", "no": "Nem", "noise": "Zaj", "other": "Egyéb", "precisionHelp": "Konkrét dátum és időpont nélkül a bejelentést csak jelzésként tudjuk rögzíteni, panaszként nem tudjuk kezelni.", "privacy": "Az Ön adatai", "privacyMore": "Technika, hozzáférés és az Ön jogai", "privacyPurpose": "A VvE Ogierssingel 263/301 – Bollandstraat 29/35 a bejelentést kezelésre, karbantartásra és zavarás kivizsgálására használja. Az arra jogosult vezetőségi tagok és a VvE-kezelő bizalmasan kezelik a tartalmat. A chipszámot külön, titkosítva tároljuk; a lakáshoz fűződő meglévő kapcsolat a VvE nyilvántartásában marad.", "privacyRights": "Hozzáféréssel, helyesbítéssel, törléssel vagy tiltakozással kapcsolatos kérdésekkel forduljon a vezetőséghez. Adja meg a bejelentési számot. A vezetőség elbírálja a kérelmet, és a meglévő nyilvántartás alapján ellenőrizheti személyazonosságát. Panaszt tehet a holland adatvédelmi hatóságnál is.", "privacyStorage": "A bejelentőhely legfeljebb 180 napig őrzi a bejelentéseket, a nem azonosítható jelzéseket legfeljebb 30 napig. Ha egy ügy hosszabb kezelést igényel, a vezetőség csak a szükségeset őrzi meg, legfeljebb az ügy lezárása után két évig. A vezetőség évente átnézi ezeket az aktákat. A munkamásolatokra ugyanez a határidő vonatkozik, és lezárás után törlik őket. Az e-mail-értesítések csak a bejelentési számot tartalmazzák.", "privacyTech": "A weboldalt a GitHub üzemelteti. A Cloudflare végzi a biztonsági ellenőrzést és fogadja a bejelentést; a tartalom és a mellékletek titkosítva tárolódnak. A Resend kizárólag a bejelentési számot tartalmazó üzenetet kézbesíti. Ezek a szolgáltatások technikai kapcsolati adatokat is feldolgoznak, például IP-címet. Az Ön IP-címét nem tároljuk a bejelentésben, és az űrlapot nem mentjük a böngésző tárolójába. Nyilvános bejelentési lista nincs.", "rateError": "Túl sok próbálkozás. Várjon egy percet, és próbálja újra.", "ready": "Bejelentése biztonságos csatornán megy el. A vezetőség belsőleg ellenőrzi a chipet.", "receiptHelp": "A beérkezés után véletlenszerű bejelentési számot kap. Őrizze meg a további kommunikációhoz. Automatikus e-mailt nem kap.", "receivedHelp": "A vezetőség elbírálja a bejelentést, és belsőleg ellenőrzi a chipet. A chipszám és a lakás itt nem jelenik meg.", "repeatDetails": "Mikor / milyen gyakran? (nem kötelező)", "repeated": "Előfordult már korábban?", "safety": "Biztonság", "saveNumber": "Őrizze meg ezt a bejelentési számot. A levelezésben ezentúl ezt a számot használja, ne a chipszámot.", "sending": "Küldés folyamatban…", "serverError": "A beérkezést nem sikerült megerősíteni. A beírt adatok megmaradtak. Kérjük, próbálja meg később. A bejelentés lehet, hogy már megérkezett; újraküldéskor említse meg a lehetséges kettőzést.", "smoke": "Füst / szag", "submit": "Bejelentés elküldése", "success": "Bejelentését megkaptuk", "tag": "A bejelentő chipszáma", "tagError": "Adjon meg egy 4–32 betűből vagy számjegyből álló chipszámot, vagy válassza a névtelen jelzést.", "tagHelp": "Másolja át a számot a chipjéről. A kezdő nullák megmaradnak. Egy korábban kiadott, letiltott chip a nyilvántartásban még felismerhető lehet.", "tagWhere": "Hol találom ezt a számot?", "tagWhereAlt": "Két chip nyíllal a fém kengyelen lévő kódra mutatva, valamint egy beviteli mező, ahová ezt a számot beírják.", "tagWhereBody": "A chip fém kengyelére kód van nyomtatva. Pontosan másolja át ezt a számot, a kezdő nullákkal együtt. Ha a chipen nincs kód, válassza a névtelen jelzést.", "tagWhereTitle": "A chipjén szereplő szám", "technical": "Műszaki hiba", "time": "Az esemény időpontja (nem kötelező)", "timeHelp": "Rotterdami helyi idő. Azt adja meg, mikor történt, nem azt, mikor tölti ki az űrlapot.", "title": "Bizalmas bejelentés a VvE felé", "truthful": "Kijelentem, hogy ezt a bejelentést a valóságnak megfelelően töltöttem ki.", "unavailable": "A bejelentőűrlap előkészítés alatt áll. A mezőket megtekintheti, de bejelentést még nem küldhet.", "unknown": "Nem tudom", "urgent": "Beázás, üzemzavar vagy más sürgős épületprobléma esetén hívja a VvE 24 órás hibaelhárító szolgálatát:", "yes": "Igen"},
"hr":{"anonWarnBack": "Natrag, upisat ću broj privjeska", "anonWarnBody": "Bez broja privjeska uprava nema na čemu temeljiti postupanje: nema upozorenja, nema sankcije, nema provjere određenog stana. Ne možemo vas ništa ni pitati ni obavijestiti. Dojava se bilježi, ali obično se ništa ne mijenja.", "anonWarnPrivacy": "Vaš broj privjeska čuva se odvojeno u šifriranom obliku i nikada se ne prikazuje drugim stanarima. Sa stanom ga putem evidencije mogu povezati samo ovlašteni članovi uprave.", "anonWarnProceed": "Ipak prijavi anonimno", "anonWarnTitle": "Anonimna prijava gotovo je nikakva prijava", "anonymous": "Nemam broj privjeska i želim poslati samo anonimnu dojavu.", "anonymousHelp": "Bez prepoznatljivog broja privjeska prijavu tretiramo isključivo kao anonimnu dojavu. Sama dojava nije osnova za upozorenje ili sankciju.", "attachmentHelp": "Najviše 3 datoteke: JPG, PNG ili PDF, do 2 MB po datoteci. Provjerite i nazive i sadržaj datoteka zbog nepotrebnih osobnih podataka.", "attachments": "Dodajte dokaz (nije obavezno)", "captcha": "Prije slanja dovršite sigurnosnu provjeru.", "captchaBlocked": "Sigurnosnu provjeru nije bilo moguće učitati. Isključite blokator oglasa ili proširenje za privatnost za ovu stranicu ili pokušajte s drugim preglednikom. Prijavu možete poslati i e-poštom.", "captchaError": "Sigurnosna provjera je istekla ili nije uspjela. Provedite je ponovno.", "category": "Vrsta prijave", "choose": "Odaberite", "close": "Zatvori", "contact": "Uprava me smije kontaktirati putem postojeće evidencije VvE-a.", "contactHelp": "Samo ako se privjesak može povezati sa stanom. Uprava će vas kontaktirati putem podataka evidentiranih za vaš stan. Prema članku 20. akta o etažiranju vlasnici su dužni prijaviti svoje najmoprimce i korisnike VvE-u.", "damage": "Šteta", "date": "Datum događaja", "description": "Opis događaja", "descriptionHelp": "Opišite što ste osobno vidjeli, čuli ili osjetili. Najmanje 20 znakova. Izbjegavajte nepotrebna imena i druge osobne podatke. Možete pisati na svom jeziku.", "dirt": "Onečišćenje", "dur1": "Manje od 15 minuta", "dur2": "Od 15 minuta do 1 sata", "dur3": "Od 1 do 3 sata", "dur4": "Od 3 do 6 sati", "dur5": "Od 6 do 12 sati", "dur6": "Dulje od 12 sati", "dur7": "Neprekidno, gotovo stalno", "dur8": "Traje i u ovom trenutku", "duration": "Koliko je trajalo?", "durationHelp": "Procjena je dovoljna. Odaberite „neprekidno” ako nije riječ o pojedinačnom događaju.", "emergency": "Ovaj obrazac nije za hitne slučajeve. U slučaju neposredne opasnosti nazovite 112.", "event": "2. Što se dogodilo?", "fileError": "Upotrijebite najviše 3 datoteke JPG, PNG ili PDF, svaka do 2 MB.", "followup": "3. Daljnji postupak", "futureError": "Datum događaja ne može biti u budućnosti.", "identity": "1. Vaš pristupni privjesak", "intro": "Ne morate navesti ime ni adresu. Upotrijebite broj pristupnog privjeska izdanog za vaš stan. Samo ovlašteni članovi uprave i upravitelj VvE-a smiju taj broj povezati sa stanom putem evidencije privjesaka. Vaš identitet neće biti otkriven drugim stanarima bez potrebe.", "invalid": "Provjerite obavezna polja.", "location": "Mjesto ili stan na koji se odnosi", "locationHelp": "Gdje se dogodilo? Ne upisujte ovdje vlastitu adresu kao kontakt ako želite ostati anonimni.", "navReport": "Prijavite problem", "navRules": "Pravila zgrade", "navUpdates": "Informacije za vlasnike", "newReport": "Pošalji novu prijavu", "no": "Ne", "noise": "Buka", "other": "Ostalo", "precisionHelp": "Bez konkretnog datuma i vremena prijavu možemo evidentirati samo kao dojavu i ne možemo je obraditi kao pritužbu.", "privacy": "Vaši podaci", "privacyMore": "Tehnologija, pristup i vaša prava", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 koristi vašu prijavu za upravljanje, održavanje i rješavanje smetnji. Ovlašteni članovi uprave i upravitelj VvE-a sadržaj tretiraju povjerljivo. Broj privjeska čuva se odvojeno u šifriranom obliku; postojeća poveznica sa stanom ostaje u evidenciji VvE-a.", "privacyRights": "Za pitanja o pristupu, ispravku, brisanju ili prigovoru obratite se upravi. Navedite broj prijave. Uprava ocjenjuje zahtjev i može provjeriti vaš identitet putem postojeće evidencije. Pritužbu možete podnijeti i nizozemskom tijelu za zaštitu podataka.", "privacyStorage": "Prijavni ured čuva prijave najviše 180 dana, a dojave bez poveznice najviše 30 dana. Ako predmet zahtijeva dulju obradu, uprava čuva samo ono što je nužno, najdulje dvije godine nakon zatvaranja predmeta. Uprava jednom godišnje pregledava te spise. Radne kopije podliježu istom roku i brišu se nakon zatvaranja. E-poruke sadrže samo broj prijave.", "privacyTech": "GitHub održava web-stranicu. Cloudflare provodi sigurnosnu provjeru i zaprima prijavu; sadržaj i privici pohranjuju se šifrirano. Resend dostavlja isključivo poruku s brojem prijave. Te usluge obrađuju i tehničke podatke o vezi, poput IP adrese. Vašu IP adresu ne pohranjujemo u prijavu i obrazac ne spremamo u pohranu preglednika. Javni popis prijava ne postoji.", "rateError": "Previše pokušaja. Pričekajte minutu i pokušajte ponovno.", "ready": "Vaša se prijava šalje zaštićeno. Uprava će interno provjeriti privjesak.", "receiptHelp": "Nakon zaprimanja dobit ćete nasumičan broj prijave. Sačuvajte ga za daljnju komunikaciju. Automatsku e-poruku nećete dobiti.", "receivedHelp": "Uprava će razmotriti prijavu i interno provjeriti privjesak. Broj privjeska i stan ovdje se ne prikazuju.", "repeatDetails": "Kada / koliko često? (nije obavezno)", "repeated": "Je li se to već događalo?", "safety": "Sigurnost", "saveNumber": "Sačuvajte ovaj broj prijave. Ubuduće u dopisivanju koristite taj broj, a ne broj privjeska.", "sending": "Šalje se…", "serverError": "Zaprimanje nije moglo biti potvrđeno. Vaš unos je i dalje ovdje. Pokušajte kasnije. Prijava je možda već stigla; pri ponovnom slanju spomenite mogući duplikat.", "smoke": "Dim / miris", "submit": "Pošalji prijavu", "success": "Vaša prijava je zaprimljena", "tag": "Broj privjeska podnositelja", "tagError": "Unesite broj privjeska od 4 do 32 slova ili znamenke ili odaberite anonimnu dojavu.", "tagHelp": "Prepišite broj sa svog privjeska. Vodeće nule ostaju. Ranije izdan, deaktiviran privjesak može i dalje biti prepoznatljiv u evidenciji.", "tagWhere": "Gdje pronalazim taj broj?", "tagWhereAlt": "Dva privjeska sa strelicom koja pokazuje na kod na metalnom nosaču i polje u koje se taj broj upisuje.", "tagWhereBody": "Na metalnom nosaču privjeska otisnut je kod. Prepišite taj broj točno, uključujući vodeće nule. Ako na privjesku nema koda, odaberite anonimnu dojavu.", "tagWhereTitle": "Broj na vašem privjesku", "technical": "Tehnički problem", "time": "Vrijeme događaja (nije obavezno)", "timeHelp": "Lokalno vrijeme u Rotterdamu. Navedite kada se dogodilo, a ne kada ispunjavate obrazac.", "title": "Povjerljiva prijava VvE-u", "truthful": "Izjavljujem da je ova prijava ispunjena istinito.", "unavailable": "Obrazac za prijavu se priprema. Možete pregledati polja, ali prijavu još ne možete poslati.", "unknown": "Ne znam", "urgent": "Za curenje, kvar ili druge hitne probleme sa zgradom nazovite danonoćnu servisnu službu VvE-a:", "yes": "Da"},
"sr":{"anonWarnBack": "Nazad, upisaću broj priveska", "anonWarnBody": "Bez broja priveska uprava nema na čemu da zasnuje postupanje: nema upozorenja, nema sankcije, nema provere određenog stana. Ne možemo ništa ni da vas pitamo ni da vam javimo. Dojava se beleži, ali obično se ništa ne menja.", "anonWarnPrivacy": "Vaš broj priveska čuva se odvojeno u šifrovanom obliku i nikada se ne prikazuje drugim stanarima. Sa stanom ga preko evidencije mogu povezati samo ovlašćeni članovi uprave.", "anonWarnProceed": "Ipak prijavi anonimno", "anonWarnTitle": "Anonimna prijava je gotovo nikakva prijava", "anonymous": "Nemam broj priveska i želim da pošaljem samo anonimnu dojavu.", "anonymousHelp": "Bez prepoznatljivog broja priveska prijavu tretiramo isključivo kao anonimnu dojavu. Sama dojava nije osnov za upozorenje ili sankciju.", "attachmentHelp": "Najviše 3 datoteke: JPG, PNG ili PDF, do 2 MB po datoteci. Proverite i nazive i sadržaj datoteka zbog nepotrebnih ličnih podataka.", "attachments": "Dodajte dokaz (nije obavezno)", "captcha": "Pre slanja završite bezbednosnu proveru.", "captchaBlocked": "Bezbednosnu proveru nije bilo moguće učitati. Isključite blokator oglasa ili dodatak za privatnost za ovu stranicu ili pokušajte sa drugim pregledačem. Prijavu možete poslati i e-poštom.", "captchaError": "Bezbednosna provera je istekla ili nije uspela. Sprovedite je ponovo.", "category": "Vrsta prijave", "choose": "Izaberite", "close": "Zatvori", "contact": "Uprava sme da me kontaktira preko postojeće evidencije VvE-a.", "contactHelp": "Samo ako privezak može da se poveže sa stanom. Uprava će vas kontaktirati preko podataka evidentiranih za vaš stan. Prema članu 20. akta o etažiranju vlasnici su dužni da prijave svoje zakupce i korisnike VvE-u.", "damage": "Šteta", "date": "Datum događaja", "description": "Opis događaja", "descriptionHelp": "Opišite šta ste lično videli, čuli ili osetili. Najmanje 20 znakova. Izbegavajte nepotrebna imena i druge lične podatke. Možete pisati na svom jeziku.", "dirt": "Zagađenje", "dur1": "Manje od 15 minuta", "dur2": "Od 15 minuta do 1 sata", "dur3": "Od 1 do 3 sata", "dur4": "Od 3 do 6 sati", "dur5": "Od 6 do 12 sati", "dur6": "Duže od 12 sati", "dur7": "Neprekidno, gotovo stalno", "dur8": "Traje i u ovom trenutku", "duration": "Koliko je trajalo?", "durationHelp": "Procena je dovoljna. Izaberite „neprekidno” ako nije reč o pojedinačnom događaju.", "emergency": "Ovaj obrazac nije za hitne slučajeve. U slučaju neposredne opasnosti pozovite 112.", "event": "2. Šta se dogodilo?", "fileError": "Upotrebite najviše 3 datoteke JPG, PNG ili PDF, svaka do 2 MB.", "followup": "3. Dalji postupak", "futureError": "Datum događaja ne može biti u budućnosti.", "identity": "1. Vaš pristupni privezak", "intro": "Ne morate navesti ime ni adresu. Upotrebite broj pristupnog priveska izdatog za vaš stan. Samo ovlašćeni članovi uprave i upravnik VvE-a smeju taj broj da povežu sa stanom preko evidencije priveska. Vaš identitet neće biti otkriven drugim stanarima bez potrebe.", "invalid": "Proverite obavezna polja.", "location": "Mesto ili stan na koji se odnosi", "locationHelp": "Gde se dogodilo? Ne upisujte ovde sopstvenu adresu kao kontakt ako želite da ostanete anonimni.", "navReport": "Prijavite problem", "navRules": "Pravila zgrade", "navUpdates": "Informacije za vlasnike", "newReport": "Pošalji novu prijavu", "no": "Ne", "noise": "Buka", "other": "Ostalo", "precisionHelp": "Bez konkretnog datuma i vremena prijavu možemo evidentirati samo kao dojavu i ne možemo je obraditi kao pritužbu.", "privacy": "Vaši podaci", "privacyMore": "Tehnologija, pristup i vaša prava", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 koristi vašu prijavu za upravljanje, održavanje i rešavanje smetnji. Ovlašćeni članovi uprave i upravnik VvE-a sadržaj tretiraju poverljivo. Broj priveska čuva se odvojeno u šifrovanom obliku; postojeća veza sa stanom ostaje u evidenciji VvE-a.", "privacyRights": "Za pitanja o pristupu, ispravci, brisanju ili prigovoru obratite se upravi. Navedite broj prijave. Uprava ocenjuje zahtev i može proveriti vaš identitet preko postojeće evidencije. Pritužbu možete podneti i holandskom telu za zaštitu podataka.", "privacyStorage": "Prijavno mesto čuva prijave najviše 180 dana, a dojave bez veze najviše 30 dana. Ako predmet zahteva duže vođenje, uprava čuva samo ono što je neophodno, najduže dve godine nakon zatvaranja predmeta. Uprava jednom godišnje pregleda te spise. Radne kopije podležu istom roku i brišu se nakon zatvaranja. E-poruke sadrže samo broj prijave.", "privacyTech": "GitHub održava sajt. Cloudflare sprovodi bezbednosnu proveru i prima prijavu; sadržaj i prilozi čuvaju se šifrovano. Resend dostavlja isključivo poruku sa brojem prijave. Te usluge obrađuju i tehničke podatke o vezi, poput IP adrese. Vašu IP adresu ne čuvamo u prijavi i obrazac ne čuvamo u memoriji pregledača. Javni spisak prijava ne postoji.", "rateError": "Previše pokušaja. Sačekajte minut i pokušajte ponovo.", "ready": "Vaša prijava se šalje zaštićeno. Uprava će interno proveriti privezak.", "receiptHelp": "Nakon prijema dobićete nasumičan broj prijave. Sačuvajte ga za dalju komunikaciju. Automatsku e-poruku nećete dobiti.", "receivedHelp": "Uprava će razmotriti prijavu i interno proveriti privezak. Broj priveska i stan se ovde ne prikazuju.", "repeatDetails": "Kada / koliko često? (nije obavezno)", "repeated": "Da li se to već dešavalo?", "safety": "Bezbednost", "saveNumber": "Sačuvajte ovaj broj prijave. Ubuduće u prepisci koristite taj broj, a ne broj priveska.", "sending": "Šalje se…", "serverError": "Prijem nije mogao da bude potvrđen. Vaš unos je i dalje ovde. Pokušajte kasnije. Prijava je možda već stigla; pri ponovnom slanju pomenite mogući duplikat.", "smoke": "Dim / miris", "submit": "Pošalji prijavu", "success": "Vaša prijava je primljena", "tag": "Broj priveska podnosioca", "tagError": "Unesite broj priveska od 4 do 32 slova ili cifre ili izaberite anonimnu dojavu.", "tagHelp": "Prepišite broj sa svog priveska. Vodeće nule ostaju. Ranije izdat, deaktiviran privezak može i dalje biti prepoznatljiv u evidenciji.", "tagWhere": "Gde nalazim taj broj?", "tagWhereAlt": "Dva priveska sa strelicom koja pokazuje na kod na metalnom nosaču i polje u koje se taj broj upisuje.", "tagWhereBody": "Na metalnom nosaču priveska odštampan je kod. Prepišite taj broj tačno, uključujući vodeće nule. Ako na privesku nema koda, izaberite anonimnu dojavu.", "tagWhereTitle": "Broj na vašem privesku", "technical": "Tehnički problem", "time": "Vreme događaja (nije obavezno)", "timeHelp": "Lokalno vreme u Roterdamu. Navedite kada se dogodilo, a ne kada popunjavate obrazac.", "title": "Poverljiva prijava VvE-u", "truthful": "Izjavljujem da je ova prijava popunjena istinito.", "unavailable": "Obrazac za prijavu se priprema. Možete pregledati polja, ali prijavu još ne možete poslati.", "unknown": "Ne znam", "urgent": "Za curenje, kvar ili druge hitne probleme sa zgradom pozovite non-stop servisnu službu VvE-a:", "yes": "Da"},
"uk":{"anonWarnBack": "Назад, я введу номер ключа", "anonWarnBody": "Без номера ключа правлінню немає на що спертися: ні попередження, ні санкції, ні перевірки конкретної квартири. Ми також не можемо нічого у вас запитати й нічого повідомити. Сигнал буде зафіксовано, але зазвичай нічого не змінюється.", "anonWarnPrivacy": "Номер вашого ключа зберігається окремо в зашифрованому вигляді й ніколи не показується іншим мешканцям. Пов’язати його з квартирою через реєстр можуть лише уповноважені члени правління.", "anonWarnProceed": "Усе одно надіслати анонімно", "anonWarnTitle": "Анонімне повідомлення — майже не повідомлення", "anonymous": "У мене немає номера ключа, і я хочу надіслати лише анонімний сигнал.", "anonymousHelp": "Без розпізнаваного номера ключа ми розглядаємо повідомлення виключно як анонімний сигнал. Сам лише сигнал не є підставою для попередження чи санкції.", "attachmentHelp": "Щонайбільше 3 файли: JPG, PNG або PDF, до 2 МБ кожен. Перевірте також назви та вміст файлів на зайві персональні дані.", "attachments": "Додати доказ (необов’язково)", "captcha": "Перед надсиланням пройдіть перевірку безпеки.", "captchaBlocked": "Не вдалося завантажити перевірку безпеки. Вимкніть блокувальник реклами чи розширення приватності для цієї сторінки або спробуйте інший браузер. Повідомити можна також електронною поштою.", "captchaError": "Перевірка безпеки минула або не вдалася. Пройдіть її ще раз.", "category": "Вид повідомлення", "choose": "Оберіть варіант", "close": "Закрити", "contact": "Правління може зв’язатися зі мною через наявний реєстр VvE.", "contactHelp": "Лише якщо ключ можна пов’язати з квартирою. Правління зв’яжеться за даними, зареєстрованими для вашої квартири. Згідно зі статтею 20 акта про поділ власники зобов’язані реєструвати своїх орендарів і користувачів у VvE.", "damage": "Пошкодження", "date": "Дата події", "description": "Опис події", "descriptionHelp": "Опишіть, що ви особисто бачили, чули або відчували. Щонайменше 20 символів. Уникайте зайвих імен та інших персональних даних. Ви можете писати своєю мовою.", "dirt": "Забруднення", "dur1": "Менше ніж 15 хвилин", "dur2": "Від 15 хвилин до 1 години", "dur3": "Від 1 до 3 годин", "dur4": "Від 3 до 6 годин", "dur5": "Від 6 до 12 годин", "dur6": "Понад 12 годин", "dur7": "Безперервно, майже постійно", "dur8": "Триває й зараз", "duration": "Скільки це тривало?", "durationHelp": "Достатньо приблизної оцінки. Оберіть «безперервно», якщо це не окремий випадок.", "emergency": "Ця форма не призначена для невідкладних випадків. У разі безпосередньої небезпеки телефонуйте 112.", "event": "2. Що сталося?", "fileError": "Використайте щонайбільше 3 файли JPG, PNG або PDF, кожен до 2 МБ.", "followup": "3. Подальші дії", "futureError": "Дата події не може бути в майбутньому.", "identity": "1. Ваш ключ доступу", "intro": "Вам не потрібно вказувати ім’я чи адресу. Скористайтеся номером ключа доступу, виданого для вашої квартири. Лише уповноважені члени правління та керівник VvE можуть пов’язати цей номер із квартирою через реєстр ключів. Вашу особу не буде розкрито іншим мешканцям без потреби.", "invalid": "Перевірте обов’язкові поля.", "location": "Місце або відповідна квартира", "locationHelp": "Де це сталося? Не вказуйте тут власну адресу як контактні дані, якщо хочете залишитися анонімним.", "navReport": "Повідомити про проблему", "navRules": "Правила будинку", "navUpdates": "Інформація для власників", "newReport": "Надіслати нове повідомлення", "no": "Ні", "noise": "Шум", "other": "Інше", "precisionHelp": "Без конкретної дати й часу ми можемо зафіксувати повідомлення лише як сигнал і не можемо розглядати його як скаргу.", "privacy": "Ваші дані", "privacyMore": "Технології, доступ і ваші права", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 використовує ваше повідомлення для управління, обслуговування та розгляду перешкод. Уповноважені члени правління та керівник VvE поводяться зі змістом конфіденційно. Номер ключа зберігається окремо в зашифрованому вигляді; наявний зв’язок із квартирою залишається в реєстрі VvE.", "privacyRights": "З питаннями про доступ, виправлення, видалення чи заперечення звертайтеся до правління. Вкажіть номер повідомлення. Правління оцінює запит і може перевірити вашу особу за наявним реєстром. Ви також можете подати скаргу до нідерландського органу із захисту даних.", "privacyStorage": "Пункт приймання зберігає повідомлення щонайбільше 180 днів, а сигнали без прив’язки — щонайбільше 30 днів. Якщо справа потребує довшого розгляду, правління зберігає лише необхідне, щонайдовше два роки після закриття справи. Правління переглядає ці справи раз на рік. Робочі копії підпадають під той самий строк і видаляються після закриття. Сповіщення електронною поштою містять лише номер повідомлення.", "privacyTech": "GitHub забезпечує роботу сайту. Cloudflare виконує перевірку безпеки та приймає повідомлення; вміст і вкладення зберігаються зашифрованими. Resend доставляє лише повідомлення з номером. Ці служби обробляють також технічні дані з’єднання, як-от IP-адресу. Ми не зберігаємо вашу IP-адресу в повідомленні та не зберігаємо форму в пам’яті браузера. Публічного переліку повідомлень немає.", "rateError": "Забагато спроб. Зачекайте хвилину та спробуйте знову.", "ready": "Ваше повідомлення надсилається захищено. Правління перевірить ключ внутрішньо.", "receiptHelp": "Після отримання ви одержите випадковий номер повідомлення. Збережіть його для подальшого спілкування. Автоматичного листа ви не отримаєте.", "receivedHelp": "Правління розгляне повідомлення та перевірить ключ внутрішньо. Номер ключа та квартира тут не показуються.", "repeatDetails": "Коли / як часто? (необов’язково)", "repeated": "Чи траплялося це раніше?", "safety": "Безпека", "saveNumber": "Збережіть цей номер повідомлення. Надалі в листуванні використовуйте його, а не номер ключа.", "sending": "Надсилання…", "serverError": "Не вдалося підтвердити отримання. Ваші дані досі тут. Спробуйте пізніше. Повідомлення могло вже надійти; за повторної спроби зазначте можливий дублікат.", "smoke": "Дим / запах", "submit": "Надіслати повідомлення", "success": "Ваше повідомлення отримано", "tag": "Номер ключа заявника", "tagError": "Введіть номер ключа з 4–32 літер або цифр чи оберіть анонімний сигнал.", "tagHelp": "Перепишіть номер зі свого ключа. Початкові нулі зберігаються. Раніше виданий, деактивований ключ може бути ще розпізнаваним у реєстрі.", "tagWhere": "Де знайти цей номер?", "tagWhereAlt": "Два ключі зі стрілкою, що вказує на код на металевій скобі, та поле, у яке вводиться цей номер.", "tagWhereBody": "На металевій скобі ключа надруковано код. Перепишіть цей номер точно, разом із початковими нулями. Якщо на ключі немає коду, оберіть анонімний сигнал.", "tagWhereTitle": "Номер на вашому ключі", "technical": "Технічна несправність", "time": "Час події (необов’язково)", "timeHelp": "Місцевий час у Роттердамі. Зазначте, коли це сталося, а не коли ви заповнюєте форму.", "title": "Конфіденційне повідомлення до VvE", "truthful": "Заявляю, що це повідомлення заповнено правдиво.", "unavailable": "Форма повідомлення готується. Ви можете переглянути поля, але надіслати повідомлення поки не можна.", "unknown": "Не знаю", "urgent": "У разі протікання, аварії чи інших термінових проблем із будинком телефонуйте до цілодобової аварійної служби VvE:", "yes": "Так"},
"ru":{"anonWarnBack": "Назад, я введу номер ключа", "anonWarnBody": "Без номера ключа правлению не на что опереться: ни предупреждения, ни санкции, ни проверки конкретной квартиры. Мы также не сможем ничего у вас спросить и ничего сообщить. Сигнал будет зафиксирован, но обычно ничего не меняется.", "anonWarnPrivacy": "Номер вашего ключа хранится отдельно в зашифрованном виде и никогда не показывается другим жильцам. Связать его с квартирой через реестр могут только уполномоченные члены правления.", "anonWarnProceed": "Всё равно отправить анонимно", "anonWarnTitle": "Анонимное сообщение — почти не сообщение", "anonymous": "У меня нет номера ключа, и я хочу передать только анонимный сигнал.", "anonymousHelp": "Без распознаваемого номера ключа мы рассматриваем сообщение исключительно как анонимный сигнал. Один лишь сигнал не является основанием для предупреждения или санкции.", "attachmentHelp": "Не более 3 файлов: JPG, PNG или PDF, до 2 МБ каждый. Проверьте также имена и содержимое файлов на лишние персональные данные.", "attachments": "Добавить доказательство (необязательно)", "captcha": "Перед отправкой пройдите проверку безопасности.", "captchaBlocked": "Не удалось загрузить проверку безопасности. Отключите блокировщик рекламы или расширение приватности для этой страницы либо попробуйте другой браузер. Сообщить можно и по электронной почте.", "captchaError": "Проверка безопасности истекла или не удалась. Пройдите её ещё раз.", "category": "Вид сообщения", "choose": "Выберите вариант", "close": "Закрыть", "contact": "Правление может связаться со мной через существующий реестр VvE.", "contactHelp": "Только если ключ можно связать с квартирой. Правление свяжется по данным, зарегистрированным для вашей квартиры. Согласно статье 20 акта о разделении собственники обязаны регистрировать своих арендаторов и пользователей в VvE.", "damage": "Повреждение", "date": "Дата происшествия", "description": "Описание происшествия", "descriptionHelp": "Опишите, что вы лично видели, слышали или чувствовали. Не менее 20 символов. Избегайте лишних имён и других персональных данных. Вы можете писать на своём языке.", "dirt": "Загрязнение", "dur1": "Менее 15 минут", "dur2": "От 15 минут до 1 часа", "dur3": "От 1 до 3 часов", "dur4": "От 3 до 6 часов", "dur5": "От 6 до 12 часов", "dur6": "Более 12 часов", "dur7": "Непрерывно, почти постоянно", "dur8": "Продолжается и сейчас", "duration": "Сколько это длилось?", "durationHelp": "Достаточно примерной оценки. Выберите «непрерывно», если речь не об отдельном случае.", "emergency": "Эта форма не предназначена для экстренных случаев. При непосредственной опасности звоните 112.", "event": "2. Что произошло?", "fileError": "Используйте не более 3 файлов JPG, PNG или PDF, каждый до 2 МБ.", "followup": "3. Дальнейшие действия", "futureError": "Дата происшествия не может быть в будущем.", "identity": "1. Ваш ключ доступа", "intro": "Указывать имя или адрес не нужно. Используйте номер ключа доступа, выданного для вашей квартиры. Только уполномоченные члены правления и управляющий VvE могут связать этот номер с квартирой через реестр ключей. Ваша личность не будет раскрыта другим жильцам без необходимости.", "invalid": "Проверьте обязательные поля.", "location": "Место или соответствующая квартира", "locationHelp": "Где это произошло? Не указывайте здесь собственный адрес как контактные данные, если хотите остаться анонимным.", "navReport": "Сообщить о проблеме", "navRules": "Правила дома", "navUpdates": "Информация для собственников", "newReport": "Отправить новое сообщение", "no": "Нет", "noise": "Шум", "other": "Другое", "precisionHelp": "Без конкретной даты и времени мы можем зафиксировать сообщение только как сигнал и не можем рассматривать его как жалобу.", "privacy": "Ваши данные", "privacyMore": "Технологии, доступ и ваши права", "privacyPurpose": "VvE Ogierssingel 263/301 – Bollandstraat 29/35 использует ваше сообщение для управления, обслуживания и рассмотрения помех. Уполномоченные члены правления и управляющий VvE обращаются с содержанием конфиденциально. Номер ключа хранится отдельно в зашифрованном виде; существующая связь с квартирой остаётся в реестре VvE.", "privacyRights": "По вопросам доступа, исправления, удаления или возражения обращайтесь в правление. Укажите номер сообщения. Правление оценивает запрос и может проверить вашу личность по существующему реестру. Вы также можете подать жалобу в нидерландский орган по защите данных.", "privacyStorage": "Пункт приёма хранит сообщения не более 180 дней, а сигналы без привязки — не более 30 дней. Если дело требует более длительного рассмотрения, правление хранит только необходимое, не дольше двух лет после закрытия дела. Правление пересматривает эти дела раз в год. Рабочие копии подпадают под тот же срок и удаляются после закрытия. Уведомления по электронной почте содержат только номер сообщения.", "privacyTech": "GitHub обеспечивает работу сайта. Cloudflare выполняет проверку безопасности и принимает сообщение; содержание и вложения хранятся в зашифрованном виде. Resend доставляет только сообщение с номером. Эти службы обрабатывают также технические данные соединения, например IP-адрес. Мы не сохраняем ваш IP-адрес в сообщении и не сохраняем форму в памяти браузера. Публичного списка сообщений нет.", "rateError": "Слишком много попыток. Подождите минуту и попробуйте снова.", "ready": "Ваше сообщение отправляется защищённо. Правление проверит ключ внутренне.", "receiptHelp": "После получения вы получите случайный номер сообщения. Сохраните его для дальнейшей переписки. Автоматическое письмо вы не получите.", "receivedHelp": "Правление рассмотрит сообщение и проверит ключ внутренне. Номер ключа и квартира здесь не отображаются.", "repeatDetails": "Когда / как часто? (необязательно)", "repeated": "Это случалось раньше?", "safety": "Безопасность", "saveNumber": "Сохраните этот номер сообщения. В дальнейшем используйте в переписке его, а не номер ключа.", "sending": "Отправляется…", "serverError": "Не удалось подтвердить получение. Ваши данные всё ещё здесь. Попробуйте позже. Сообщение могло уже поступить; при повторной попытке укажите возможный дубликат.", "smoke": "Дым / запах", "submit": "Отправить сообщение", "success": "Ваше сообщение получено", "tag": "Номер ключа заявителя", "tagError": "Введите номер ключа из 4–32 букв или цифр либо выберите анонимный сигнал.", "tagHelp": "Перепишите номер со своего ключа. Ведущие нули сохраняются. Ранее выданный, отключённый ключ может по-прежнему определяться в реестре.", "tagWhere": "Где найти этот номер?", "tagWhereAlt": "Два ключа со стрелкой, указывающей на код на металлической скобе, и поле, в которое вводится этот номер.", "tagWhereBody": "На металлической скобе ключа напечатан код. Перепишите этот номер точно, включая ведущие нули. Если на ключе кода нет, выберите анонимный сигнал.", "tagWhereTitle": "Номер на вашем ключе", "technical": "Техническая неисправность", "time": "Время происшествия (необязательно)", "timeHelp": "Местное время в Роттердаме. Укажите, когда это произошло, а не когда вы заполняете форму.", "title": "Конфиденциальное сообщение в VvE", "truthful": "Заявляю, что это сообщение заполнено достоверно.", "unavailable": "Форма сообщения готовится. Вы можете просмотреть поля, но отправить сообщение пока нельзя.", "unknown": "Не знаю", "urgent": "При протечке, аварии или других срочных проблемах со зданием звоните в круглосуточную аварийную службу VvE:", "yes": "Да"},
"zh":{"anonWarnBack": "返回，我填写标签编号", "anonWarnBody": "没有标签编号，管理委员会就无从着手：不能警告、不能处罚、也不能针对某一套公寓进行核查。我们同样无法向您提问或告知结果。线索会被记录，但通常不会有任何改变。", "anonWarnPrivacy": "您的标签编号单独加密保存，绝不会展示给其他住户。只有获授权的管理委员才能通过记录将其与公寓对应。", "anonWarnProceed": "仍然匿名提交", "anonWarnTitle": "匿名报告几乎等于没有报告", "anonymous": "我没有标签编号，只想提交匿名线索。", "anonymousHelp": "无法识别标签编号的报告仅作为匿名线索处理。单独的线索不能作为警告或处罚的依据。", "attachmentHelp": "最多3个JPG、PNG或PDF文件，每个不超过2 MB。请检查文件名及内容中是否有不必要的个人信息。", "attachments": "添加证据（选填）", "captcha": "发送前请完成安全验证。", "captchaBlocked": "安全验证无法加载。请为本页面关闭广告拦截或隐私插件，或换一个浏览器。您也可以通过电子邮件报告。", "captchaError": "安全验证已过期或失败，请重新完成。", "category": "报告类别", "choose": "请选择", "close": "关闭", "contact": "管理委员会可以通过现有记录联系我。", "contactHelp": "仅当标签可对应公寓时适用。管理委员会将通过您公寓登记的信息与您联系。根据分割规章第20条，业主有义务向业主委员会登记其租户和使用人。", "damage": "损坏", "date": "事发日期", "description": "事件描述", "descriptionHelp": "描述您亲自看到、听到或闻到的情况，至少20个字符。避免不必要的姓名或其他个人信息。可以使用您自己的语言。", "dirt": "垃圾／污染", "dur1": "少于15分钟", "dur2": "15分钟至1小时", "dur3": "1至3小时", "dur4": "3至6小时", "dur5": "6至12小时", "dur6": "超过12小时", "dur7": "持续不断，几乎不停", "dur8": "目前仍在持续", "duration": "持续了多久？", "durationHelp": "估算即可。如果不是单次事件，请选择“持续不断”。", "emergency": "此表不适用于紧急情况。如有直接危险，请拨打112。", "event": "2. 发生了什么？", "fileError": "最多上传3个JPG、PNG或PDF文件，每个不超过2 MB。", "followup": "3. 后续处理", "futureError": "事件日期不能在未来。", "identity": "1. 您的门禁标签", "intro": "无需填写姓名或地址。请使用发给您公寓的门禁标签编号。只有获授权的管理委员和物业经理可以通过现有记录将编号与公寓对应。没有必要时，不会向其他住户透露您的身份。", "invalid": "请检查必填字段。", "location": "事发地点或相关公寓", "locationHelp": "事情在哪里发生？如果您希望保持匿名，请勿在此填写您自己的联系地址。", "navReport": "提交报告", "navRules": "建筑规则", "navUpdates": "业主动态", "newReport": "提交新报告", "no": "否", "noise": "噪音", "other": "其他", "precisionHelp": "没有具体日期和时间，我们只能将其记录为线索，无法作为正式投诉处理。", "privacy": "您的信息", "privacyMore": "技术、访问和您的权利", "privacyPurpose": "Ogierssingel 263/301 – Bollandstraat 29/35业主委员会将报告用于楼宇管理、维修和滋扰处理。获授权的管理委员和物业经理会保密处理。标签编号单独加密保存，与公寓的现有对应关系仍留在业主委员会的记录中。", "privacyRights": "如需查阅、更正、删除或提出异议，请联系管理委员会并提供报告编号。管理委员会会评估请求，并可能通过现有记录核实身份。您也可以向荷兰数据保护局投诉。", "privacyStorage": "本系统最多保存报告180天，无法对应公寓的线索最多保存30天。如需更长处理时间，管理委员会仅保留必要信息，最长至案件结案后两年。管理委员会每年清理一次这些档案。处理人制作的工作副本适用相同期限，结案后即予删除。发送给处理人的邮件仅包含报告编号。", "privacyTech": "GitHub托管网站。Cloudflare提供安全验证并接收报告，内容及附件加密保存。Resend仅向处理人发送包含报告编号的通知。这些服务还会处理IP地址等技术连接数据。我们不会在报告中保存您的IP地址，也不在浏览器存储中保存表单。没有公开报告列表。", "rateError": "尝试次数过多，请等待一分钟再试。", "ready": "报告将安全发送。管理委员会会在内部核对标签。", "receiptHelp": "收到报告后，您将获得随机报告编号，请保存以便后续联系。您不会收到自动邮件。", "receivedHelp": "管理委员会将审核报告并在内部核对标签。此处不会显示标签编号或公寓信息。", "repeatDetails": "何时／多久一次？（选填）", "repeated": "以前发生过吗？", "safety": "安全", "saveNumber": "请保存此编号，以后联系时使用报告编号，不要使用门禁标签编号。", "sending": "正在发送…", "serverError": "无法确认是否收到。您的内容仍在页面中，请稍后重试。报告可能已经送达，重试时请说明可能重复。", "smoke": "烟雾／异味", "submit": "提交报告", "success": "已收到您的报告", "tag": "报告人的标签编号", "tagError": "请填写4至32个字母或数字的标签编号，或选择匿名线索。", "tagHelp": "请照抄标签编号，保留开头的零。已停用的旧标签仍可能在记录中被识别。", "tagWhere": "在哪里找到这个编号？", "tagWhereAlt": "两个标签，箭头指向金属扣上的编号，以及填写该编号的输入框。", "tagWhereBody": "标签的金属扣上印有一串编号。请完全照抄，包括开头的零。如果标签上没有编号，请选择匿名线索。", "tagWhereTitle": "标签上的编号", "technical": "技术故障", "time": "事发时间（选填）", "timeHelp": "鹿特丹当地时间。请填写事情发生的时间，而非您填写此表的时间。", "title": "向业主委员会保密报告", "truthful": "我声明此报告如实填写。", "unavailable": "报告表正在准备中。您可以查看字段，但目前无法提交。", "unknown": "不知道", "urgent": "漏水、故障或其他紧急楼宇问题，请拨打业主委员会24小时报修电话：", "yes": "是"}
};
